FROM (VALUES
($j$bo-phan-trang-tren-cay-canh-rau$j$, $j$bat-benh$j$, $j$🐛 Bọ phấn trắng trên cây cảnh và rau: nhận biết đàn ruồi trắng li ti và cách diệt tận gốc$j$, $j$Bọ phấn trắng là côn trùng nhỏ 1–2mm, cánh trắng như rắc bột, sống mặt dưới lá và bay tung lên khi chạm vào cây. Chúng chích hút nhựa làm lá vàng, tiết mật gây muội đen và truyền virus xoăn lá. Xử lý bằng bẫy dính vàng, xịt nước mặt dưới lá, cắt lá nặng và giữ cây thông thoáng.$j$, $j$[{"type": "p", "text": "Lật mặt dưới lá cà chua, ớt, bông giấy hay cây kiểng mà thấy một đám \"ruồi\" trắng nhỏ xíu bay tung lên như bụi phấn — đó là **bọ phấn trắng** (còn gọi ruồi trắng). Một vài con không đáng lo, nhưng chúng sinh sản rất nhanh, mùa khô nóng chỉ vài tuần là phủ kín mặt dưới lá."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Bemisia_tabaci_from_USDA_1.jpg/960px-Bemisia_tabaci_from_USDA_1.jpg", "caption": "Bọ phấn trắng trưởng thành ở mặt dưới lá"}, {"type": "h2", "text": "🔍 Nhận biết bọ phấn trắng"}, {"type": "list", "items": ["Con trưởng thành dài 1–2mm, cánh trắng phủ bột sáp, đậu ở **mặt dưới lá**, bay lên khi lay cây.", "Trứng và ấu trùng là những chấm dẹt màu vàng nhạt, trong suốt, bám chặt mặt dưới lá, không di chuyển.", "Lá có lớp mật dính bóng, sau đó đen lại như bồ hóng ([muội đen](/benh-cay/muoi-den)).", "Lá vàng lốm đốm, cây chậm lớn; rau, ớt, cà chua có thể bị xoăn lá."], "ordered": false}, {"type": "p", "text": "Dễ nhầm với [rệp muội](/benh-cay/rep-muoi) (không có cánh trắng, bám đọt non thành đám) và [rệp sáp](/benh-cay/rep-sap) (phủ sáp như bông, gần như đứng yên)."}, {"type": "h2", "text": "🔎 Bọ phấn trắng gây hại thế nào?"}, {"type": "p", "text": "Chúng chích hút nhựa lá, tiết mật làm nấm muội đen phát triển, che ánh sáng của lá. Nguy hiểm hơn, bọ phấn **truyền virus** gây [vàng xoăn lá](/benh-cay/xoan-la-virus) trên cà chua, ớt, bí — bệnh virus không có thuốc chữa, chỉ nhổ bỏ cây. Vì vậy với rau ăn trái, phải diệt bọ phấn sớm."}, {"type": "h2", "text": "🛠️ Cách diệt bọ phấn trắng"}, {"type": "list", "items": ["**Bẫy dính màu vàng**: bọ phấn bị màu vàng hút. Treo bẫy ngang tầm tán, cách 1–2m một tấm; vừa diệt vừa báo mật độ.", "**Xịt nước mạnh mặt dưới lá** vào sáng sớm, 2–3 ngày một lần trong 2 tuần, rửa trôi trứng và ấu trùng.", "**Cắt bỏ lá bị nặng** (nhiều ấu trùng) cho vào túi kín rồi bỏ đi, không vứt tại chỗ.", "**Xà phòng sinh học hoặc dầu neem** pha theo hướng dẫn, phun kỹ mặt dưới lá lúc chiều mát; lặp lại sau 5–7 ngày vì trứng nở lứa mới.", "Bị nặng trên rau, cây ăn trái mới dùng thuốc có đăng ký cho bọ phấn, đọc kỹ nhãn và thời gian cách ly."], "ordered": true}, {"type": "note", "title": "⚠️ Lưu ý an toàn", "text": "Với rau và cây ăn trái, ưu tiên bẫy dính, xịt nước, xà phòng sinh học. Nếu phải dùng thuốc bảo vệ thực vật: chọn thuốc có đăng ký, dùng đúng liều, đeo găng tay khẩu trang và chỉ thu hoạch sau thời gian cách ly ghi trên nhãn. Xem [hướng dẫn dùng thuốc an toàn](/chinh-sach/thuoc-bvtv-an-toan)."}, {"type": "h2", "text": "🛡️ Phòng bọ phấn quay lại"}, {"type": "list", "items": ["Kiểm tra mặt dưới lá mỗi tuần, nhất là mùa khô.", "Không bón dư đạm — đọt non mềm mập là món khoái khẩu của bọ phấn.", "Cây mới mua về để riêng 1 tuần, kiểm tra kỹ rồi mới đặt cạnh cây khác.", "Nhổ cỏ dại quanh vườn rau, nơi bọ phấn trú ẩn."], "ordered": false}, {"type": "p", "text": "Xem thêm [cách đọc nhãn thuốc trước khi dùng](/goc-cham-cay/doc-nhan-thuoc-bvtv-truoc-khi-dung) và [trồng ớt chậu tại nhà](/goc-cham-cay/trong-ot-chau)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Bemisia_tabaci_from_USDA_1.jpg/960px-Bemisia_tabaci_from_USDA_1.jpg$j$, 3, ARRAY[$j$xoan-la-virus$j$,$j$muoi-den$j$,$j$rep-muoi$j$]::text[], ARRAY[$j$bọ phấn trắng$j$,$j$sâu hại$j$,$j$rau sạch$j$]::text[], $j$Bọ phấn trắng (ruồi trắng) trên cây cảnh, rau: dấu hiệu nhận biết, tác hại, cách diệt bằng bẫy dính vàng, xịt nước, dầu neem và cách phòng tái phát.$j$, $j$2026-10-22 06:30:00+07$j$),
($j$tuoi-cay-bang-nuoc-gi-tot$j$, $j$cham-soc$j$, $j$💧 Tưới cây bằng nước gì tốt nhất: nước máy, nước giếng, nước mưa, nước vo gạo?$j$, $j$Nước mưa là nước tưới tốt nhất cho cây cảnh. Nước máy dùng được nhưng nên hứng để qua đêm cho bớt clo, đặc biệt với cây nhạy như lan chi, đuôi công. Nước giếng ở miền Tây cần thử độ mặn, phèn trước khi tưới. Nước vo gạo chỉ nên dùng loãng, thỉnh thoảng, vì dễ làm chua đất và hôi chậu.$j$, $j$[{"type": "p", "text": "Cùng một cây, cùng lượng nước, nhưng tưới bằng nước khác nhau có thể cho kết quả khác nhau: lá xanh mướt hay cháy đầu lá, đất tơi hay đóng váng trắng. Ở miền Tây, nước giếng nhiễm phèn, mặn càng khiến chuyện chọn nước tưới quan trọng hơn."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Watering_plants_with_a_green_watering_can_during_a_sunny_day_in_a_garden_setting.jpg/960px-Watering_plants_with_a_green_watering_can_during_a_sunny_day_in_a_garden_setting.jpg", "caption": "Bình tưới cây. Ảnh: Shixart1985, CC BY 2.0, Wikimedia Commons"}, {"type": "h2", "text": "🌧️ Nước mưa: tốt nhất"}, {"type": "p", "text": "Nước mưa mềm, hơi chua nhẹ, không có clo hay muối khoáng tích tụ — gần như loại cây nào cũng thích. Hứng nước mưa vào lu, thùng có nắp (tránh muỗi đẻ trứng), bỏ đi nước mưa đầu mùa vì cuốn theo bụi mái nhà."}, {"type": "h2", "text": "🚰 Nước máy: dùng được, nên để qua đêm"}, {"type": "list", "items": ["Nước máy có clo khử trùng. Phần lớn cây chịu được, nhưng cây nhạy như [lan chi](/san-pham/lan-chi), [đuôi công](/san-pham/duoi-cong-xanh), [lan ý](/san-pham/lan-y) dễ cháy đầu lá.", "Hứng nước ra xô, để mở nắp qua đêm cho clo bay bớt và nước bằng nhiệt độ phòng.", "Mỗi vài tháng tưới thật đẫm cho nước chảy qua đáy chậu để rửa muối khoáng tích tụ."], "ordered": false}, {"type": "h2", "text": "🪣 Nước giếng: cần thử trước"}, {"type": "list", "items": ["**Nước nhiễm phèn** (có mùi tanh, để lâu đóng váng vàng, lắng cặn đỏ): để lắng, lọc qua cát rồi mới tưới; phèn nặng làm đất chua, rễ thâm.", "**Nước nhiễm mặn** (mùa khô, vùng ven biển): cây cảnh bị cháy mép lá, rụng lá. Đo độ mặn trước khi tưới — xem [phòng mặn cho cây mùa khô](/goc-cham-cay/phong-man-cho-cay-san-vuon).", "Nước giếng sạch, không phèn mặn thì tưới tốt."], "ordered": false}, {"type": "h2", "text": "🍚 Nước vo gạo: dùng loãng, thỉnh thoảng"}, {"type": "p", "text": "Nước vo gạo có ít tinh bột, vitamin nhóm B, khoáng. Dùng loãng 1 phần nước vo với 2–3 phần nước sạch, khoảng 1–2 tuần một lần thì không hại. Dùng đặc và thường xuyên dễ làm đất chua, bốc mùi, sinh nấm mốc và ruồi nấm — nhất là chậu để trong nhà. Đây không phải là phân bón thay thế."}, {"type": "h2", "text": "❓ Các loại nước khác"}, {"type": "table", "rows": [["Loại nước", "Có nên dùng?"], ["Nước đá lạnh", "Không — lạnh đột ngột làm sốc rễ cây nhiệt đới"], ["Nước nóng, nước luộc rau", "Để nguội hẳn mới dùng; nước luộc có muối thì không dùng"], ["Nước rửa cá, rửa thịt", "Hôi, dễ sinh giòi — không dùng cho chậu trong nhà"], ["Nước máy lọc RO", "Dùng được, nhưng không có khoáng — cần bón phân đều"], ["Nước hồ cá cảnh khi thay", "Tốt cho cây ngoài trời, có chất hữu cơ"]]}, {"type": "p", "text": "Xem thêm [tưới cây trong nhà bao lâu một lần](/goc-cham-cay/tuoi-cay-trong-nha-dung-cach) và [lá cháy mép, khô đầu lá do đâu](/goc-cham-cay/la-chay-mep-kho-dau-la)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Watering_plants_with_a_green_watering_can_during_a_sunny_day_in_a_garden_setting.jpg/960px-Watering_plants_with_a_green_watering_can_during_a_sunny_day_in_a_garden_setting.jpg$j$, 3, ARRAY[$j$chay-re-do-phan$j$]::text[], ARRAY[$j$tưới cây$j$,$j$nước tưới$j$,$j$cây trong nhà$j$]::text[], $j$Tưới cây bằng nước gì tốt: nước mưa, nước máy, nước giếng, nước vo gạo, nước đá? Ưu nhược điểm, cách xử lý nước máy, nước giếng nhiễm phèn, mặn ở miền Tây.$j$, $j$2026-10-22 12:00:00+07$j$),
($j$trong-rau-den-tai-nha$j$, $j$rau-sach$j$, $j$🥬 Trồng rau dền tại nhà trong thùng xốp: gieo hạt, tưới, bón để 25–30 ngày có rau ăn$j$, $j$Rau dền là rau dễ trồng nhất mùa nắng: gieo hạt rải trên đất tơi, phủ mỏng, tưới phun nhẹ mỗi ngày, khoảng 25–30 ngày là cắt được. Rau dền ưa nắng, chịu nóng tốt, cần đất thoát nước. Cắt chừa gốc thì rau tái sinh thêm 1–2 lứa.$j$, $j$[{"type": "p", "text": "Rau dền (dền đỏ, dền xanh, dền cơm) mọc khỏe, ít sâu bệnh, lại thích nắng nóng — rất hợp trồng sân thượng, ban công ở miền Tây. Một thùng xốp nhỏ là đủ có rau nấu canh cho gia đình vài bữa."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Amaranthus_tricolor_4zz.jpg/960px-Amaranthus_tricolor_4zz.jpg", "caption": "Rau dền trồng tại vườn nhà. Ảnh: Photo by David J. Stang, CC BY-SA 4.0, Wikimedia Commons"}, {"type": "h2", "text": "🪴 Chuẩn bị thùng và đất"}, {"type": "list", "items": ["Thùng xốp, chậu sâu 15–20cm, khoan nhiều lỗ thoát nước ở đáy.", "Đất: đất thịt tơi trộn phân trùn quế hoặc phân chuồng hoai (khoảng 3 phần đất, 1 phần phân), thêm xơ dừa cho tơi.", "Đặt nơi có nắng ít nhất 5–6 giờ/ngày."], "ordered": false}, {"type": "h2", "text": "🌱 Gieo hạt rau dền"}, {"type": "list", "items": ["Hạt dền rất nhỏ: trộn hạt với ít cát khô cho dễ rải đều.", "Rải đều lên mặt đất đã tưới ẩm, phủ một lớp đất mịn thật mỏng (khoảng 0,5cm) hoặc chỉ ém nhẹ tay.", "Tưới bằng bình phun sương để hạt không trôi.", "Hạt nảy mầm sau 3–5 ngày."], "ordered": true}, {"type": "h2", "text": "💧 Tưới và bón"}, {"type": "list", "items": ["Tưới nhẹ mỗi ngày vào sáng sớm hoặc chiều mát, giữ đất ẩm, không để đọng nước.", "Khi cây có 3–4 lá thật, tỉa bớt cây mọc dày, cây cách cây khoảng 5–7cm (cây tỉa ăn được).", "Sau khi tỉa 1 tuần, tưới thêm nước phân hữu cơ loãng hoặc phân trùn quế hòa nước."], "ordered": false}, {"type": "h2", "text": "✂️ Thu hoạch"}, {"type": "p", "text": "Khoảng 25–30 ngày sau gieo, cây cao 20–25cm là cắt được. Cắt cách gốc 5–7cm, chừa vài lá, bón thêm ít phân hữu cơ — rau sẽ ra nhánh cho lứa sau. Dền ra hoa thì lá cứng, nên thu trước khi trổ bông."}, {"type": "h2", "text": "🐛 Sâu bệnh thường gặp"}, {"type": "p", "text": "Sâu ăn lá, rệp ở đọt non mùa khô; thối gốc khi mưa dầm đọng nước. Phần lớn xử lý bằng bắt tay, xịt nước, giữ thùng thoát nước tốt. Xem [lá thủng lỗ do sâu hay ốc](/benh-cay/sau-an-la) và [ốc sên ăn lá](/goc-cham-cay/oc-sen-an-la-ban-cong)."}, {"type": "p", "text": "Trồng thêm rau khác: [rau muống thùng xốp](/goc-cham-cay/trong-rau-muong-thung-xop), [rau cải](/goc-cham-cay/trong-rau-cai-thung-xop), [rau thơm ban công](/goc-cham-cay/trong-rau-thom-ban-cong)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Amaranthus_tricolor_4zz.jpg/960px-Amaranthus_tricolor_4zz.jpg$j$, 2, '{}'::text[], ARRAY[$j$rau dền$j$,$j$rau sạch$j$,$j$thùng xốp$j$]::text[], $j$Cách trồng rau dền trong thùng xốp, chậu tại nhà: chọn hạt, gieo, tưới, bón phân hữu cơ, thu hoạch sau 25–30 ngày và cắt tỉa cho rau ra lứa mới.$j$, $j$2026-10-22 19:30:00+07$j$),
($j$vo-trung-ba-ca-phe-vo-chuoi-bon-cay$j$, $j$thuoc-phan-bon$j$, $j$🧪 Vỏ trứng, bã cà phê, vỏ chuối bón cây: cái nào có ích thật, cái nào chỉ là lời đồn?$j$, $j$Vỏ trứng, bã cà phê, vỏ chuối đều có chút dinh dưỡng nhưng phân giải rất chậm và không thay được phân bón. Cách dùng đúng là ủ hoai cùng rác bếp rồi mới trộn đất. Chôn trực tiếp vào chậu dễ gây mốc, ruồi, hôi và chua đất; bã cà phê rải dày còn làm mặt đất đóng váng, khó thấm nước.$j$, $j$[{"type": "p", "text": "Mạng xã hội đầy mẹo \"bón cây bằng đồ bỏ đi\": vỏ trứng giã nhỏ, bã cà phê, vỏ chuối ngâm nước. Có mẹo đúng một phần, có mẹo gần như vô ích, và có cách dùng còn làm chậu cây hỏng. Cùng xem từng thứ."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Cangkang_telur_ayam_sebagai_bahan_pembuatan_kompos.jpg/960px-Cangkang_telur_ayam_sebagai_bahan_pembuatan_kompos.jpg", "caption": "Vỏ trứng và rác bếp dùng để ủ phân. Ảnh: Ahmad Mukhlis, CC BY 4.0, Wikimedia Commons"}, {"type": "h2", "text": "🥚 Vỏ trứng"}, {"type": "list", "items": ["Chứa chủ yếu **canxi**, gần như không có đạm, lân, kali.", "Vỏ nguyên mảnh nằm trong đất hàng năm không tan — cây gần như không hưởng được.", "Dùng đúng: rửa sạch, phơi khô, **xay thật mịn** rồi trộn vào đất khi thay chậu hoặc cho vào thùng ủ.", "Hữu ích nhất với cà chua, ớt (giảm thối đáy trái do thiếu canxi) — nhưng chỉ khi tưới đều đặn."], "ordered": false}, {"type": "h2", "text": "☕ Bã cà phê"}, {"type": "list", "items": ["Có ít đạm, hơi chua; tốt khi **ủ cùng rác bếp** thành phân hữu cơ.", "Rải dày trực tiếp lên mặt chậu: bã kết lại thành lớp cứng, nước khó thấm, dễ mốc xanh.", "Không dùng nhiều cho cây ưa đất trung tính, cây mọng nước.", "Rải mỏng quanh luống rau ngoài trời thì không sao."], "ordered": false}, {"type": "h2", "text": "🍌 Vỏ chuối"}, {"type": "list", "items": ["Có **kali**, ít lân — hợp cây ra hoa, ra trái khi đã phân giải.", "Chôn vỏ tươi vào chậu: thối, hôi, kéo ruồi, kiến, chuột; cây chưa kịp dùng.", "\"Nước ngâm vỏ chuối\" chứa rất ít dinh dưỡng, lại dễ lên men chua.", "Dùng đúng: cắt nhỏ, ủ hoai rồi mới bón; hoặc phơi khô giòn, xay vụn trộn đất."], "ordered": false}, {"type": "h2", "text": "📋 So sánh nhanh"}, {"type": "table", "rows": [["Thứ", "Dinh dưỡng chính", "Cách dùng đúng", "Sai lầm hay gặp"], ["Vỏ trứng", "Canxi", "Xay mịn, trộn đất, ủ", "Bỏ nguyên mảnh lên mặt chậu"], ["Bã cà phê", "Ít đạm", "Ủ cùng rác bếp", "Rải dày lên chậu → mốc"], ["Vỏ chuối", "Kali", "Ủ hoai hoặc phơi khô xay", "Chôn vỏ tươi → hôi, ruồi"]]}, {"type": "h2", "text": "💡 Cách tốt nhất: ủ chung thành phân hữu cơ"}, {"type": "p", "text": "Gom vỏ trứng, bã cà phê, vỏ chuối, rau thừa vào thùng ủ cùng lá khô, sau 2–3 tháng có phân hữu cơ tơi xốp, không mùi — xem [ủ phân hữu cơ từ rác bếp tại nhà](/goc-cham-cay/u-phan-huu-co-tu-rac-bep). Cây cảnh trồng chậu vẫn cần phân bón đầy đủ đạm – lân – kali; xem [phân tan chậm hay phân hòa tan](/goc-cham-cay/phan-tan-cham-va-phan-hoa-tan) và [đọc chỉ số NPK](/goc-cham-cay/doc-chi-so-npk-tren-bao-phan)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Cangkang_telur_ayam_sebagai_bahan_pembuatan_kompos.jpg/960px-Cangkang_telur_ayam_sebagai_bahan_pembuatan_kompos.jpg$j$, 2, '{}'::text[], ARRAY[$j$phân tự làm$j$,$j$vỏ trứng$j$,$j$bã cà phê$j$]::text[], $j$Vỏ trứng, bã cà phê, vỏ chuối bón cây có tốt không? Sự thật về dinh dưỡng, cách ủ đúng, liều dùng và những sai lầm làm chậu cây mốc, hôi, chua đất.$j$, $j$2026-10-23 06:30:00+07$j$),
($j$cay-xanh-cho-phong-tam-nha-ve-sinh$j$, $j$decor$j$, $j$🏡 Cây xanh cho phòng tắm, nhà vệ sinh: chọn cây chịu ẩm, ít sáng và cách đặt cho khỏi mốc$j$, $j$Phòng tắm ẩm là chỗ lý tưởng cho cây ưa ẩm như dương xỉ, lan ý, trầu bà — miễn là có chút ánh sáng từ cửa sổ hoặc đèn. Phòng tắm không cửa sổ thì chọn lưỡi hổ, bật đèn đủ giờ hoặc luân phiên mang cây ra chỗ sáng mỗi tuần. Đặt cây xa vòi sen nóng, kệ thoáng để chậu không đọng nước.$j$, $j$[{"type": "p", "text": "Một chậu cây xanh trên bệ cửa sổ hay góc kệ làm phòng tắm tươi mát hẳn. Độ ẩm cao là lợi thế với nhiều cây kiểng lá — nhưng ánh sáng ít và nước bắn tung tóe là hai điều phải tính."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Ecosystem_in_bathroom_-_51442495643.jpg/960px-Ecosystem_in_bathroom_-_51442495643.jpg", "caption": "Cây xanh trang trí phòng tắm. Ảnh: The Urban Botanist Images, CC BY 2.0, Wikimedia Commons"}, {"type": "h2", "text": "🛒 Cây hợp phòng tắm"}, {"type": "table", "rows": [["Cây", "Vì sao hợp", "Lưu ý"], ["Dương xỉ", "Ưa ẩm cao, lá mềm mại", "Cần sáng tán xạ"], ["Lan ý", "Ưa ẩm, chịu bóng, có hoa trắng", "Nhựa gây ngứa — đặt cao"], ["Trầu bà, đế vương", "Chịu bóng, chịu ẩm", "Lau lá định kỳ"], ["Lưỡi hổ", "Chịu tối, ít tưới", "Hợp phòng không cửa sổ; đừng tưới nhiều"], ["Lan chi", "Treo đẹp, chịu ẩm", "Cần sáng nhẹ"]]}, {"type": "h2", "text": "☀️ Phòng tắm không cửa sổ thì sao?"}, {"type": "list", "items": ["Bóng đèn trong phòng tắm thường chỉ bật vài phút — không đủ cho cây.", "Chọn lưỡi hổ và **luân phiên**: mỗi tuần đem cây ra chỗ sáng 2–3 ngày.", "Hoặc gắn một bóng LED trồng cây bật theo hẹn giờ.", "Không đủ sáng lâu ngày, cây vống và rụng lá dần."], "ordered": false}, {"type": "h2", "text": "📍 Đặt cây ở đâu cho đúng?"}, {"type": "list", "items": ["Bệ cửa sổ, kệ cao, góc xa vòi sen — tránh nước nóng, xà phòng bắn vào lá.", "Không đặt sát máy nước nóng, đèn sưởi.", "Dùng chậu có đĩa lót, kê cao để đáy chậu không đọng nước, không làm ố kệ.", "Giỏ treo gần cửa sổ là cách tiết kiệm chỗ."], "ordered": false}, {"type": "h2", "text": "💧 Tưới ít hơn bạn nghĩ"}, {"type": "p", "text": "Không khí ẩm làm đất khô chậm. Kiểm tra đất bằng ngón tay, chỉ tưới khi mặt đất đã khô — tưới theo thói quen dễ làm cây [thối rễ](/benh-cay/thoi-re). Mở cửa, bật quạt hút sau khi tắm để phòng thoáng, hạn chế [đốm lá do nấm](/benh-cay/dom-la-nam)."}, {"type": "products", "title": "Cây hợp phòng tắm", "slugs": ["duong-xi", "lan-y", "luoi-ho", "lan-chi", "trau-ba-de-vuong-xanh"]}, {"type": "p", "text": "Xem thêm [trang trí bằng cây treo, giỏ treo](/goc-cham-cay/cay-treo-gio-treo-trang-tri) và [cây đặt phòng ngủ](/goc-cham-cay/cay-dat-phong-ngu)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Ecosystem_in_bathroom_-_51442495643.jpg/960px-Ecosystem_in_bathroom_-_51442495643.jpg$j$, 2, ARRAY[$j$dom-la-nam$j$,$j$thoi-re$j$]::text[], ARRAY[$j$phòng tắm$j$,$j$decor$j$,$j$cây ưa ẩm$j$]::text[], $j$Cây xanh đặt phòng tắm, nhà vệ sinh: cây chịu ẩm, ít sáng (dương xỉ, lan ý, trầu bà, lưỡi hổ), cách đặt chậu, xử lý phòng không cửa sổ và tránh mốc.$j$, $j$2026-10-23 19:30:00+07$j$),
($j$chon-cay-lam-hang-rao-nha-pho$j$, $j$cam-nang$j$, $j$📗 Chọn cây làm hàng rào xanh cho nhà phố, nhà vườn: cây chịu nắng, mau phủ, dễ cắt tỉa$j$, $j$Hàng rào xanh đẹp cần cây chịu nắng, mọc dày, chịu cắt tỉa và hợp chiều cao mong muốn. Rào thấp dưới 1m hợp bụi hoa như mai địa thảo cho viền lối đi; rào che chắn 1,5–2m hợp cau trắng, trúc, cây bụi lá dày; muốn có rau thì trồng rau ngót, mồng tơi leo lưới. Trồng dày, cắt ngọn sớm để rào kín gốc.$j$, $j$[{"type": "p", "text": "Hàng rào cây xanh mềm mại hơn tường gạch, che bụi, che tầm nhìn từ đường vào nhà và làm khoảng sân mát hẳn. Chọn đúng cây ngay từ đầu giúp rào kín nhanh, ít phải trồng dặm và dễ giữ dáng."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Hedge_in_Brussels.jpg/960px-Hedge_in_Brussels.jpg", "caption": "Hàng rào cây xanh cắt tỉa gọn. Ảnh: IsouM, CC BY-SA 4.0, Wikimedia Commons"}, {"type": "h2", "text": "📏 Chọn theo chiều cao mong muốn"}, {"type": "table", "rows": [["Mục đích", "Chiều cao", "Gợi ý"], ["Viền lối đi, bồn hoa", "Dưới 60cm", "Cây hoa bụi thấp (mai địa thảo, cúc), cỏ viền"], ["Rào thấp phân khu sân", "60cm–1m", "Cây bụi lá nhỏ chịu cắt tỉa"], ["Che chắn tầm nhìn", "1,5–2m", "Cau trắng trồng hàng, trúc, cây bụi lá dày"], ["Rào có rau ăn", "1–1,5m", "Rau ngót, mồng tơi leo lưới"]]}, {"type": "h2", "text": "☀️ Chịu nắng hay chịu bóng?"}, {"type": "p", "text": "Hầu hết hàng rào nhà phố hứng nắng gắt cả ngày, nên ưu tiên cây chịu nắng. Rào dưới bóng cây lớn, hướng Bắc thì chọn cây bụi chịu bóng. Xem thêm [cây cho ban công nắng gắt](/goc-cham-cay/cay-ban-cong-nang-gat)."}, {"type": "h2", "text": "🪴 Trồng thế nào để rào nhanh kín?"}, {"type": "list", "items": ["Đào rãnh rộng 40–50cm, trộn phân chuồng hoai vào đất.", "Cây bụi trồng cách nhau 30–50cm; trồng so le hai hàng nếu muốn kín nhanh.", "Cây dạng cau, trúc: cách nhau 50–80cm tùy cỡ.", "Tưới mỗi ngày 1–2 tháng đầu cho bén rễ — xem [chăm cây công trình mới trồng](/goc-cham-cay/cham-cay-cong-trinh-moi-trong)."], "ordered": false}, {"type": "h2", "text": "✂️ Cắt tỉa giữ dáng"}, {"type": "list", "items": ["**Cắt ngọn sớm** khi cây còn nhỏ để cây đâm nhánh từ gốc — rào kín chân, không bị \"trống chân\".", "Cắt dáng hơi thang: chân rộng hơn ngọn để phần gốc vẫn nhận được nắng.", "Mùa mưa cây mọc nhanh, tỉa 3–4 tuần một lần; mùa khô thưa hơn."], "ordered": false}, {"type": "h2", "text": "⚠️ Lưu ý"}, {"type": "list", "items": ["Tránh cây có gai nhọn sát lối đi có trẻ nhỏ.", "Hỏi quy định của khu dân cư về chiều cao rào, khoảng lùi.", "Cây lớn cho bóng mát nên trồng cách tường, móng nhà đủ xa — xem [chọn cây công trình cho đường phố, khu dân cư](/goc-cham-cay/chon-cay-cong-trinh-duong-pho-san-truong)."], "ordered": false}, {"type": "products", "title": "Cây sân vườn, công trình tại vườn", "slugs": ["cau-trang", "mai-dia-thao", "bang-dai-loan", "chuoi-re-quat"]}, {"type": "p", "text": "Cần số lượng lớn cho dự án: [gửi yêu cầu báo giá sỉ](/bao-gia-si)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Hedge_in_Brussels.jpg/960px-Hedge_in_Brussels.jpg$j$, 2, '{}'::text[], ARRAY[$j$hàng rào xanh$j$,$j$cây sân vườn$j$,$j$nhà phố$j$]::text[], $j$Chọn cây làm hàng rào xanh cho nhà phố, nhà vườn miền Tây: theo chiều cao, ánh sáng, mục đích che chắn hay trang trí; khoảng cách trồng và cách cắt tỉa cho kín.$j$, $j$2026-10-24 06:30:00+07$j$),
($j$dat-cay-theo-huong-nha-phong-thuy$j$, $j$phong-thuy$j$, $j$🍀 Đặt cây theo hướng trong nhà: quan niệm phong thủy dân gian và điều ánh sáng thực tế cho phép$j$, $j$Theo quan niệm phong thủy dân gian, mỗi hướng hợp một hành: Đông, Đông Nam thuộc Mộc nên hợp cây lá xanh; Nam thuộc Hỏa hợp cây lá đỏ; Tây, Tây Bắc thuộc Kim hợp cây lá trắng bạc. Nhưng cây chỉ đẹp khi đủ sáng: hãy chọn hướng theo phong thủy rồi chọn loài cây theo ánh sáng thật của chỗ đó.$j$, $j$[{"type": "p", "text": "\"Hướng Đông đặt cây gì, hướng Tây đặt cây gì?\" là câu hỏi rất nhiều người gửi tới shop. Bài này tóm tắt quan niệm phong thủy dân gian về hướng — và quan trọng không kém: **mỗi hướng nhận bao nhiêu nắng**, vì cây hợp hướng mà thiếu sáng thì cũng không đẹp nổi."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Bright_windowsill_%28Unsplash%29.jpg/960px-Bright_windowsill_%28Unsplash%29.jpg", "caption": "Cây cảnh đặt cạnh cửa sổ có nắng"}, {"type": "h2", "text": "🍀 Hướng và ngũ hành theo quan niệm dân gian"}, {"type": "table", "rows": [["Hướng", "Hành", "Màu cây thường được chọn", "Gợi ý cây"], ["Đông, Đông Nam", "Mộc", "Lá xanh", "Trầu bà đế vương xanh, lan ý, dương xỉ"], ["Nam", "Hỏa", "Lá đỏ, hồng", "Phú quý, vạn lộc, đế vương đỏ"], ["Tây, Tây Bắc", "Kim", "Lá trắng, bạc", "Ngân hậu, ngọc ngân, bạch mã"], ["Bắc", "Thủy", "Lá xanh đậm, trắng", "Lưỡi hổ, lan ý"], ["Tây Nam, Đông Bắc, trung tâm", "Thổ", "Lá vàng, nâu", "Đế vương vàng, đế vương nâu"]]}, {"type": "p", "text": "Đây là quan niệm dân gian để tham khảo khi bày trí, không có cơ sở khoa học. Xem thêm [chọn cây theo mệnh ngũ hành](/goc-cham-cay/chon-cay-theo-menh-ngu-hanh)."}, {"type": "h2", "text": "☀️ Ánh sáng thật của từng hướng (ở Việt Nam)"}, {"type": "table", "rows": [["Cửa sổ hướng", "Ánh sáng", "Cây hợp"], ["Đông", "Nắng sáng dịu, hết nắng trước trưa", "Hầu hết cây kiểng lá, cây ra hoa"], ["Nam", "Sáng nhiều, mùa khô có nắng xiên", "Cây ưa sáng; cây chịu bóng đặt lùi vào trong"], ["Tây", "Nắng chiều gắt, nóng", "Cây chịu nắng; cây lá mỏng dễ cháy"], ["Bắc", "Sáng tán xạ, ít nắng trực tiếp", "Cây chịu bóng"]]}, {"type": "h2", "text": "🛠️ Kết hợp hai điều"}, {"type": "list", "items": ["Chọn hướng / vị trí theo ý muốn phong thủy.", "Đo ánh sáng thực tế ở chỗ đó (xem [ánh sáng cho cây trong nhà](/goc-cham-cay/anh-sang-cho-cay-trong-nha)).", "Trong các cây \"hợp hướng\", chọn loài chịu được ánh sáng đó.", "Ví dụ: muốn cây lá đỏ (Hỏa) ở cửa sổ hướng Tây nắng gắt → đặt lùi 1–2m, có rèm, tránh [cháy lá do nắng](/benh-cay/chay-la-do-nang)."], "ordered": false}, {"type": "h2", "text": "⚠️ Những điều nên tránh"}, {"type": "list", "items": ["Đừng vì \"hợp hướng\" mà đặt cây ưa bóng sát cửa kính nắng chiều.", "Cây héo, cây chết nên thay sớm — theo dân gian là điều không tốt, theo thực tế là chỗ sinh sâu bệnh.", "Xem thêm [những điều kiêng kỵ khi đặt cây trong nhà](/goc-cham-cay/kieng-ky-khi-dat-cay-trong-nha)."], "ordered": false}, {"type": "products", "title": "Cây theo màu lá", "slugs": ["trau-ba-de-vuong-xanh", "phu-quy", "ngan-hau", "luoi-ho", "trau-ba-de-vuong-vang"]}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Bright_windowsill_%28Unsplash%29.jpg/960px-Bright_windowsill_%28Unsplash%29.jpg$j$, 2, ARRAY[$j$chay-la-do-nang$j$]::text[], ARRAY[$j$phong thủy$j$,$j$hướng nhà$j$,$j$cây trong nhà$j$]::text[], $j$Đặt cây cảnh theo hướng nhà Đông, Tây, Nam, Bắc theo quan niệm phong thủy dân gian; kết hợp với ánh sáng thực tế từng hướng để chọn cây sống khỏe.$j$, $j$2026-10-24 12:00:00+07$j$),
($j$lat-la-mai-vang-truoc-tet$j$, $j$theo-mua$j$, $j$🌦️ Lặt lá mai vàng trước Tết: lặt ngày nào, cách làm và chăm sau lặt để mai nở đúng dịp$j$, $j$Nhà vườn miền Nam thường lặt lá mai vàng khoảng giữa tháng Chạp âm lịch, tức 25–35 ngày trước Tết tùy thời tiết: trời nóng lặt muộn hơn, trời lạnh lặt sớm hơn. Trước lặt 1–2 tuần bón phân kali, hạn chế tưới; lặt sạch lá, giữ nụ; sau lặt tưới đều lại và theo dõi nụ để điều chỉnh.$j$, $j$[{"type": "p", "text": "Lặt lá mai là việc mà nhà nào chưng mai vàng ở miền Nam cũng hồi hộp mỗi năm: lặt sớm quá hoa nở trước Tết, lặt muộn quá thì mùng 1 mai vẫn còn nụ. Không có ngày \"chuẩn\" cho mọi cây, nhưng có những nguyên tắc nhà vườn vẫn dùng."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Ochna_integerrima_02.JPG/960px-Ochna_integerrima_02.JPG", "caption": "Mai vàng nở hoa ngày Tết. Ảnh: Prenn, CC BY-SA 3.0, Wikimedia Commons"}, {"type": "h2", "text": "📅 Lặt lá mai vào ngày nào?"}, {"type": "list", "items": ["Thông thường: khoảng **giữa tháng Chạp âm lịch** (ngày 10–20 tháng Chạp), tức **25–35 ngày trước Tết**.", "**Trời nóng, nắng nhiều**: mai nở nhanh — lặt muộn hơn (gần 25 ngày).", "**Trời se lạnh, âm u**: mai nở chậm — lặt sớm hơn (gần 35 ngày).", "Cây trồng đất khỏe nở nhanh hơn cây trồng chậu, cây già cỗi.", "Quan sát nụ: nụ đã to bằng hạt tiêu tới hạt đậu xanh, vảy nụ căng là cây sẵn sàng."], "ordered": false}, {"type": "h2", "text": "🛠️ Chuẩn bị trước khi lặt"}, {"type": "list", "items": ["1–2 tuần trước lặt: bón phân có lân, kali để nụ chắc, hoa bền màu.", "Vài ngày trước lặt: giảm tưới cho lá hơi rũ, lặt dễ và cây \"đánh thức\" nụ khi tưới lại.", "Cắt tỉa cành khô, cành sâu bệnh trước."], "ordered": false}, {"type": "h2", "text": "🍃 Cách lặt lá"}, {"type": "list", "items": ["Dùng tay bẻ ngang cuống lá, **chừa lại một đoạn cuống ngắn**, không giật làm tróc vỏ, gãy nụ.", "Lặt sạch hết lá trên cây (trừ khi muốn giữ vài lá non ở ngọn theo ý thích).", "Ngay sau lặt: tưới đẫm để cây kích nụ phát triển.", "Có thể phun nước rửa sạch thân cành."], "ordered": true}, {"type": "h2", "text": "🔍 Theo dõi và điều chỉnh sau lặt"}, {"type": "table", "rows": [["Tình trạng nụ", "Cách xử lý dân gian thường dùng"], ["Nụ lớn nhanh, có thể nở sớm", "Che bớt nắng, giảm tưới, đưa vào chỗ mát"], ["Nụ chậm, có thể nở muộn", "Tưới nước ấm, tăng nắng, bón thêm phân kali theo hướng dẫn"], ["Nụ khô, rụng", "Kiểm tra sâu bệnh, thiếu nước, nắng gắt"]]}, {"type": "note", "title": "💡 Lưu ý", "text": "Thời gian trên là kinh nghiệm phổ biến của nhà vườn miền Nam, thay đổi theo giống mai, tuổi cây và thời tiết từng năm. Cây mai lâu năm có nhật ký các năm trước là tài liệu chính xác nhất cho chính cây đó."}, {"type": "h2", "text": "🌱 Sau Tết chăm mai thế nào?"}, {"type": "p", "text": "Hoa tàn thì cắt bỏ hết nụ, hoa, trái non; tỉa cành, bón phân hữu cơ để cây ra lá mới hồi sức. Xem thêm [chăm cây sau Tết](/goc-cham-cay/cham-cay-sau-tet) và [chuẩn bị cây cảnh đón Tết](/goc-cham-cay/chuan-bi-cay-canh-don-tet)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Ochna_integerrima_02.JPG/960px-Ochna_integerrima_02.JPG$j$, 2, '{}'::text[], ARRAY[$j$mai vàng$j$,$j$lặt lá mai$j$,$j$cây Tết$j$]::text[], $j$Lặt lá mai vàng trước Tết ngày nào? Cách tính ngày lặt theo thời tiết, chuẩn bị trước khi lặt, cách lặt đúng và chăm sau lặt để mai nở đúng mùng 1 Tết.$j$, $j$2026-10-24 19:30:00+07$j$),
($j$la-cay-bi-thung-lo-nguyen-nhan$j$, $j$bat-benh$j$, $j$🐛 Lá cây bị thủng lỗ, khuyết mép: do sâu, ốc sên hay bọ cánh cứng? Cách đoán đúng thủ phạm$j$, $j$Lá thủng lỗ hoặc khuyết mép gần như luôn do sâu, ốc sên hoặc bọ cánh cứng ăn. Phân biệt bằng dấu vết: có phân sâu đen là sâu; có vệt nhớt sáng bóng là ốc sên; lỗ nhỏ tròn li ti là bọ nhảy, bọ cánh cứng. Soi cây vào ban đêm bằng đèn pin là cách bắt quả tang nhanh nhất.$j$, $j$[{"type": "p", "text": "Sáng ra thấy lá cây lỗ chỗ như bị ai bấm lỗ, mép lá khuyết từng mảng — mà nhìn mãi không thấy con gì. Thủ phạm thường trốn kỹ ban ngày. Chỉ cần đọc dấu vết là đoán được khá chính xác, khỏi phun thuốc bừa."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Rumex_acetosa_var._hortensis_%28Gem%C3%BCse_Ampfer%29_mit_einem_Raupen_%28Ametastegia_equiseti%29_Befall-2-Josef_Schlaghecken.jpg/960px-Rumex_acetosa_var._hortensis_%28Gem%C3%BCse_Ampfer%29_mit_einem_Raupen_%28Ametastegia_equiseti%29_Befall-2-Josef_Schlaghecken.jpg", "caption": "Lá bị sâu ăn khuyết, thủng nhiều lỗ. Ảnh: Schlaghecken Josef, CC BY 4.0, Wikimedia Commons"}, {"type": "h2", "text": "🔍 Đọc dấu vết để đoán thủ phạm"}, {"type": "table", "rows": [["Dấu vết trên cây", "Thủ phạm thường gặp", "Ăn lúc nào"], ["Lỗ to, mép lá khuyết nham nhở, có viên phân đen dưới lá", "Sâu ăn lá (sâu non của bướm, ngài)", "Ngày lẫn đêm, trốn mặt dưới lá"], ["Lỗ to giữa lá, có vệt nhớt khô sáng bóng", "Ốc sên, sên trần", "Ban đêm, sau mưa"], ["Nhiều lỗ nhỏ tròn li ti như kim châm", "Bọ nhảy, bọ cánh cứng nhỏ", "Ban ngày, nhảy đi khi chạm"], ["Lá bị cắt rời từng mảnh hình bán nguyệt đều", "Ong cắt lá", "Ban ngày — ít hại, không cần xử lý"], ["Đường ngoằn ngoèo trắng bạc trong lá", "Sâu vẽ bùa (không phải lỗ thủng)", "—"]]}, {"type": "h2", "text": "🔦 Bắt quả tang vào ban đêm"}, {"type": "p", "text": "Khoảng 8–9 giờ tối, cầm đèn pin soi mặt dưới lá, đọt non, mép chậu và đáy chậu. Ốc sên, sâu ăn đêm sẽ lộ diện. Bắt tay bỏ vào hũ nước muối là cách diệt sạch, an toàn nhất cho cây trong nhà và rau."}, {"type": "h2", "text": "🛠️ Xử lý theo từng thủ phạm"}, {"type": "h3", "text": "Sâu ăn lá"}, {"type": "list", "items": ["Bắt tay sâu buổi sáng sớm, kiểm tra mặt dưới lá, nơi có ổ trứng thì ngắt bỏ cả lá.", "Rau và cây ăn trái bị nhiều: dùng chế phẩm sinh học trị sâu (như chế phẩm vi khuẩn Bt) theo hướng dẫn trên bao bì.", "Xem chi tiết ở [sâu ăn lá](/benh-cay/sau-an-la)."], "ordered": false}, {"type": "h3", "text": "Ốc sên, sên trần"}, {"type": "p", "text": "Dọn lá mục, gạch đá ẩm quanh chậu; rải vòng tro bếp hoặc cát khô quanh gốc; đặt bẫy bằng lá rau úp sát đất để sáng ra gom. Hướng dẫn kỹ ở bài [ốc sên ăn lá cây ban công](/goc-cham-cay/oc-sen-an-la-ban-cong)."}, {"type": "h3", "text": "Bọ nhảy, bọ cánh cứng nhỏ"}, {"type": "p", "text": "Hay gặp trên rau cải. Che lưới mịn cho luống rau từ lúc gieo, xới đất phơi nắng trước khi trồng vụ mới, không trồng cải liên tục trên cùng một chỗ."}, {"type": "note", "title": "⚠️ Lưu ý an toàn", "text": "Ưu tiên bắt tay, bẫy, che lưới. Nếu phải dùng thuốc trên rau: chọn thuốc có đăng ký cho đúng loại sâu, đọc kỹ nhãn, tuân thủ thời gian cách ly trước khi hái. Xem [hướng dẫn dùng thuốc an toàn](/chinh-sach/thuoc-bvtv-an-toan)."}, {"type": "h2", "text": "❓ Lá thủng rồi có lành lại không?"}, {"type": "p", "text": "Không — lỗ đã thủng thì giữ nguyên, nhưng cây vẫn quang hợp bằng phần lá còn lại. Chỉ cần diệt được thủ phạm, lá mới ra sẽ lành lặn. Lá bị ăn quá nửa có thể cắt bỏ cho cây gọn đẹp."}, {"type": "p", "text": "Xem thêm [trồng rau cải thùng xốp không cần thuốc](/goc-cham-cay/trong-rau-cai-thung-xop) và [thư viện bệnh cây](/benh-cay)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Rumex_acetosa_var._hortensis_%28Gem%C3%BCse_Ampfer%29_mit_einem_Raupen_%28Ametastegia_equiseti%29_Befall-2-Josef_Schlaghecken.jpg/960px-Rumex_acetosa_var._hortensis_%28Gem%C3%BCse_Ampfer%29_mit_einem_Raupen_%28Ametastegia_equiseti%29_Befall-2-Josef_Schlaghecken.jpg$j$, 3, ARRAY[$j$sau-an-la$j$,$j$oc-sen$j$]::text[], ARRAY[$j$lá thủng lỗ$j$,$j$sâu ăn lá$j$,$j$ốc sên$j$]::text[], $j$Lá cây bị thủng lỗ, khuyết mép là do sâu, ốc sên hay bọ cánh cứng? Cách phân biệt qua dấu vết, bắt quả tang ban đêm và xử lý an toàn cho cây cảnh, rau.$j$, $j$2026-10-25 06:30:00+07$j$),
($j$cham-cay-trong-phong-may-lanh$j$, $j$cham-soc$j$, $j$🌿 Chăm cây trong phòng máy lạnh văn phòng: đặt chỗ nào, tưới sao để lá không khô cháy$j$, $j$Cây trong phòng máy lạnh hay bị khô mép lá vì không khí khô và gió lạnh thổi thẳng. Đặt cây cách cửa gió máy lạnh ít nhất 2m, gần cửa sổ có ánh sáng, tưới khi mặt đất khô 2–3cm, tăng độ ẩm bằng khay sỏi nước. Chọn cây chịu máy lạnh như lưỡi hổ, ngân hậu, trầu bà đế vương.$j$, $j$[{"type": "p", "text": "Cây đặt văn phòng thường đẹp được vài tuần đầu rồi bắt đầu khô mép lá, rụng lá, đất lúc khô nứt lúc úng. Nguyên nhân hầu như không phải cây \"không hợp phòng\", mà là ba thứ: **gió máy lạnh, không khí khô và lịch tưới thất thường**."}, {"type": "image", "file": "https://cdn.stocksnap.io/img-thumbs/960w/UDIGU0A2SN.jpg", "caption": "Cây xanh trên bàn làm việc văn phòng"}, {"type": "h2", "text": "🔎 Máy lạnh ảnh hưởng cây thế nào?"}, {"type": "list", "items": ["Máy lạnh hút ẩm: độ ẩm phòng có thể xuống thấp, lá thoát nước nhanh, mép lá khô cháy.", "Gió lạnh thổi thẳng làm lá cây nhiệt đới bị sốc, quăn, rụng.", "Không khí khô là điều kiện ưa thích của [nhện đỏ](/benh-cay/nhen-do).", "Cuối tuần, ngày lễ máy lạnh tắt, phòng kín nóng bí — cây chịu chênh lệch lớn."], "ordered": false}, {"type": "h2", "text": "📍 Đặt cây ở đâu trong văn phòng?"}, {"type": "list", "items": ["Cách cửa gió máy lạnh **ít nhất 2m**, không nằm trên đường gió thổi.", "Gần cửa sổ có rèm là tốt nhất; cây xa cửa sổ cần chọn loại chịu bóng.", "Bàn làm việc dưới đèn huỳnh quang, LED: hợp cây nhỏ chịu bóng.", "Tránh đặt trên nóc máy in, cạnh máy tính tỏa nhiệt."], "ordered": false}, {"type": "p", "text": "Xem thêm [cây văn phòng chịu bóng theo từng vị trí](/goc-cham-cay/cay-van-phong-chiu-bong-it-tuoi)."}, {"type": "h2", "text": "💧 Tưới cây văn phòng thế nào?"}, {"type": "list", "items": ["Tưới khi mặt đất khô 2–3cm — thử bằng ngón tay, không tưới theo lịch cố định.", "Phòng lạnh đất khô chậm hơn ngoài trời, cây thường cần ít nước hơn bạn nghĩ.", "Giao cho **một người** phụ trách tưới, tránh mỗi người tưới một ít làm cây úng.", "Trước kỳ nghỉ dài: tưới đẫm, dời cây xa cửa sổ nắng — xem [cách giữ cây khi đi vắng](/goc-cham-cay/cham-cay-khi-di-vang)."], "ordered": false}, {"type": "h2", "text": "💦 Tăng độ ẩm quanh cây"}, {"type": "list", "items": ["Đặt chậu lên **khay sỏi có nước** (đáy chậu không chạm nước).", "Xếp nhiều cây gần nhau tạo vùng ẩm chung.", "Phun sương nhẹ buổi sáng cho cây lá mỏng; cây lá dày như lưỡi hổ không cần.", "Lau lá bằng khăn ẩm 2 tuần một lần — vừa sạch bụi vừa kiểm tra nhện ([lau lá đúng cách](/goc-cham-cay/lau-la-cat-tia-cay-kieng-la))."], "ordered": false}, {"type": "h2", "text": "🛒 Cây nào hợp phòng máy lạnh?"}, {"type": "table", "rows": [["Cây", "Vì sao hợp"], ["Lưỡi hổ", "Lá dày, chịu khô, ít tưới"], ["Ngân hậu, bạch mã", "Chịu bóng, chịu máy lạnh khá"], ["Trầu bà đế vương", "Lá dày bóng, bền"], ["Lan ý", "Chịu bóng; cần đất ẩm đều, phun sương"], ["Đuôi công", "Đẹp nhưng nhạy không khí khô — cần khay sỏi nước"]]}, {"type": "products", "title": "Cây hợp phòng máy lạnh", "slugs": ["luoi-ho", "ngan-hau", "trau-ba-de-vuong-xanh", "bach-ma-hoang-tu", "lan-y"]}]$j$, $j$https://cdn.stocksnap.io/img-thumbs/960w/UDIGU0A2SN.jpg$j$, 2, ARRAY[$j$nhen-do$j$,$j$heo-thieu-nuoc$j$]::text[], ARRAY[$j$cây văn phòng$j$,$j$phòng máy lạnh$j$,$j$cây trong nhà$j$]::text[], $j$Chăm cây trong phòng máy lạnh, văn phòng: vị trí đặt, khoảng cách với máy lạnh, cách tưới, tăng độ ẩm, cuối tuần không ai tưới và cây hợp phòng lạnh.$j$, $j$2026-10-25 19:30:00+07$j$),
($j$trong-mong-toi-leo-gian-tai-nha$j$, $j$rau-sach$j$, $j$🥬 Trồng mồng tơi leo giàn ở ban công, hàng rào: vừa có rau ăn quanh năm vừa che nắng$j$, $j$Mồng tơi dễ trồng bằng hạt hoặc giâm ngọn, ưa nắng và đất ẩm, leo giàn nhanh nên vừa có rau vừa làm màn che nắng ban công. Ngâm hạt qua đêm cho dễ nảy mầm, cắm giàn khi cây cao 15–20cm, tưới đều mỗi ngày, bấm ngọn thường xuyên để cây ra nhiều nhánh non.$j$, $j$[{"type": "p", "text": "Mồng tơi là rau quen thuộc của mâm cơm miền Tây — nấu canh cua, canh tôm. Cây leo nhanh, sống lâu, chỉ cần một góc nắng và vài cọc làm giàn là có rau ăn liên tục cả năm, lại thành màn xanh che nắng cho ban công."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Basella_alba_leaves_27052014.jpg/960px-Basella_alba_leaves_27052014.jpg", "caption": "Mồng tơi leo giàn. Ảnh: Joydeep, CC BY-SA 3.0, Wikimedia Commons"}, {"type": "h2", "text": "🌱 Trồng bằng hạt hoặc giâm ngọn"}, {"type": "list", "items": ["**Hạt**: vỏ cứng, nên ngâm nước ấm 6–8 tiếng (qua đêm) rồi gieo sâu 1cm; nảy mầm sau khoảng 1 tuần.", "**Giâm ngọn**: cắt ngọn mồng tơi mua chợ dài 15–20cm, tỉa bớt lá, cắm vào đất ẩm nơi râm mát; vài ngày là ra rễ."], "ordered": false}, {"type": "h2", "text": "🪴 Chậu, đất và chỗ trồng"}, {"type": "list", "items": ["Chậu hoặc thùng sâu 25cm trở lên, có lỗ thoát nước; trồng sát lan can, hàng rào.", "Đất tơi giàu mùn, trộn phân chuồng hoai hoặc phân trùn quế.", "Nắng nhiều thì lá dày, xanh; thiếu nắng thân mảnh, lá nhỏ."], "ordered": false}, {"type": "h2", "text": "🪜 Làm giàn"}, {"type": "p", "text": "Khi cây cao 15–20cm, cắm cọc tre hoặc căng lưới, dây cho cây leo. Dây mồng tơi tự quấn; lúc đầu quấn nhẹ thân vào cọc theo chiều kim đồng hồ để cây bám. Ban công cao tầng nhiều gió nên buộc giàn chắc."}, {"type": "h2", "text": "💧 Tưới và bón"}, {"type": "list", "items": ["Mồng tơi thích ẩm: mùa nắng tưới mỗi ngày, ngày nắng gắt tưới cả sáng chiều.", "Mỗi 2 tuần tưới phân hữu cơ hòa nước hoặc rắc phân trùn quế quanh gốc.", "Thiếu nước cây nhanh ra hoa, lá nhỏ và dai."], "ordered": false}, {"type": "h2", "text": "✂️ Thu hoạch liên tục"}, {"type": "p", "text": "Khoảng 30–40 ngày sau trồng bắt đầu hái ngọn non dài 15–20cm. Mỗi lần hái là một lần bấm ngọn, cây ra thêm nhiều nhánh mới. Ngắt bỏ chùm hoa nếu muốn cây tập trung ra lá; để lại vài chùm trái chín tím đen lấy hạt cho vụ sau."}, {"type": "p", "text": "Xem thêm [trồng rau thơm ban công](/goc-cham-cay/trong-rau-thom-ban-cong) và [trang trí ban công chung cư nhỏ](/goc-cham-cay/trang-tri-ban-cong-chung-cu-nho)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Basella_alba_leaves_27052014.jpg/960px-Basella_alba_leaves_27052014.jpg$j$, 2, '{}'::text[], ARRAY[$j$mồng tơi$j$,$j$rau sạch$j$,$j$rau leo giàn$j$]::text[], $j$Cách trồng mồng tơi tại nhà: gieo hạt, giâm ngọn, làm giàn leo ban công hàng rào, tưới, bón phân và thu hoạch ngọn non liên tục quanh năm.$j$, $j$2026-10-26 06:30:00+07$j$),
($j$cay-thieu-kali-thieu-lan-nhan-biet-qua-la$j$, $j$thuoc-phan-bon$j$, $j$🧪 Cây thiếu kali, thiếu lân, thiếu magie: nhận biết qua màu lá và cách bổ sung đúng$j$, $j$Thiếu kali làm mép lá già vàng rồi cháy nâu; thiếu lân làm lá già tím đỏ, cây chậm lớn, ít hoa; thiếu magie làm lá già vàng giữa các gân, gân vẫn xanh. Các dấu hiệu này thường bắt đầu ở lá già. Bổ sung bằng phân NPK cân đối hoặc phân có trung vi lượng, nhưng trước hết hãy loại trừ tưới sai và úng rễ.$j$, $j$[{"type": "p", "text": "Lá cây đổi màu không phải lúc nào cũng do sâu bệnh. Khi thiếu một chất dinh dưỡng, cây \"báo\" bằng những kiểu đổi màu khá đặc trưng. Đọc được tín hiệu đó giúp bón đúng thứ cây cần, không bón tràn lan."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Tomate_Blatt_Kalimangel.jpg/960px-Tomate_Blatt_Kalimangel.jpg", "caption": "Lá cháy mép, vàng — dấu hiệu thường gặp khi thiếu kali. Ảnh: Goldlocki, CC BY-SA 3.0, Wikimedia Commons"}, {"type": "h2", "text": "🔍 Bảng nhận biết nhanh"}, {"type": "table", "rows": [["Thiếu chất", "Lá nào bị trước", "Dấu hiệu"], ["Đạm (N)", "Lá già", "Vàng đều cả lá, cây còi, lá nhỏ"], ["Lân (P)", "Lá già", "Lá xanh sẫm rồi ửng tím đỏ, cây chậm lớn, ít hoa"], ["Kali (K)", "Lá già", "Mép lá vàng rồi cháy nâu, lá có thể xoăn mép"], ["Magie (Mg)", "Lá già", "Vàng giữa các gân, gân còn xanh, thành hình xương cá"], ["Sắt (Fe)", "Lá non", "Lá non vàng nhạt, gân xanh rõ"], ["Canxi (Ca)", "Lá non, trái", "Đọt non biến dạng; cà chua thối đáy trái"]]}, {"type": "p", "text": "Mẹo nhớ: chất **di động** trong cây (đạm, lân, kali, magie) thiếu thì lá **già** biểu hiện trước — cây rút chất từ lá già nuôi lá non. Chất **ít di động** (sắt, canxi) thiếu thì lá **non** bị trước. Xem thêm [vàng lá do thiếu đạm](/benh-cay/vang-la-thieu-dam) và [vàng lá gân xanh do thiếu sắt](/benh-cay/vang-la-thieu-sat)."}, {"type": "h2", "text": "⚠️ Loại trừ trước khi bón thêm phân"}, {"type": "list", "items": ["**Úng rễ, thối rễ**: rễ hỏng không hút được chất nên lá vàng giống thiếu dinh dưỡng — bón thêm còn hại.", "**Bón dư phân** cũng làm cháy mép lá giống thiếu kali — xem [cháy rễ do bón phân quá liều](/benh-cay/chay-re-do-phan).", "**Thiếu sáng** làm lá nhạt màu.", "**Lá già tự nhiên** vàng rụng từng lá một — bình thường."], "ordered": false}, {"type": "h2", "text": "🛠️ Bổ sung thế nào cho đúng?"}, {"type": "list", "items": ["Cây kiểng lá: phân NPK cân đối (như 20-20-20) pha loãng định kỳ thường đủ cả đạm, lân, kali.", "Cây ra hoa, ra trái: dùng loại nhiều lân khi sắp ra hoa, nhiều kali khi nuôi trái.", "Thiếu magie, sắt: chọn phân có ghi **trung – vi lượng** trên bao.", "Bón theo đúng liều ghi trên bao, chia nhỏ nhiều lần; cây trồng chậu nên pha loãng hơn.", "Lá đã đổi màu thường không xanh lại hẳn; theo dõi **lá mới ra** để biết bón đúng chưa."], "ordered": false}, {"type": "p", "text": "Xem thêm [đọc chỉ số NPK trên bao phân](/goc-cham-cay/doc-chi-so-npk-tren-bao-phan) và [phân bón lá và phân bón gốc](/goc-cham-cay/phan-bon-la-va-phan-bon-goc)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Tomate_Blatt_Kalimangel.jpg/960px-Tomate_Blatt_Kalimangel.jpg$j$, 2, ARRAY[$j$vang-la-thieu-dam$j$,$j$vang-la-thieu-sat$j$,$j$chay-re-do-phan$j$]::text[], ARRAY[$j$thiếu dinh dưỡng$j$,$j$phân bón$j$,$j$vàng lá$j$]::text[], $j$Nhận biết cây thiếu kali, thiếu lân, thiếu magie, thiếu đạm qua màu lá. Bảng phân biệt, cách bổ sung phân đúng và những trường hợp dễ nhầm với bệnh.$j$, $j$2026-10-26 19:30:00+07$j$),
($j$cay-xanh-cho-nha-bep$j$, $j$decor$j$, $j$🏡 Cây xanh cho nhà bếp: rau thơm bệ cửa sổ, cây kiểng chịu nóng và những chỗ không nên đặt cây$j$, $j$Nhà bếp hợp nhất với vài chậu rau thơm nhỏ ở bệ cửa sổ sáng (húng quế, tía tô, hành lá) và cây kiểng chịu nóng, chịu bóng như lưỡi hổ, trầu bà, lan chi. Đặt cây xa bếp lửa, lò nướng, máy hút mùi và bồn rửa có nước bắn; lau lá định kỳ vì dầu mỡ bám làm lá bí.$j$, $j$[{"type": "p", "text": "Một góc bếp có vài chậu xanh vừa đẹp mắt vừa tiện: với tay là có nắm húng quế, cọng hành. Nhưng bếp nóng, có hơi dầu mỡ, chỗ thì sáng chỗ thì tối — chọn đúng cây và đúng chỗ thì cây mới bền."}, {"type": "image", "file": "https://live.staticflickr.com/3061/2593135672_292699fc40_b.jpg", "caption": "Rau thơm trồng chậu ở bệ cửa sổ bếp"}, {"type": "h2", "text": "🌿 Rau thơm ở bệ cửa sổ"}, {"type": "list", "items": ["Húng quế, tía tô, rau răm, hành lá, ngò: cần nắng ít nhất 4–5 giờ/ngày — chỉ hợp cửa sổ sáng.", "Chậu nhỏ 12–15cm, có lỗ thoát nước, đĩa lót.", "Cắt ngọn thường xuyên để cây ra nhánh.", "Cách trồng từng loại: xem [trồng rau thơm ở ban công](/goc-cham-cay/trong-rau-thom-ban-cong) và [trồng hành lá từ gốc hành](/goc-cham-cay/trong-hanh-la-tai-nha)."], "ordered": false}, {"type": "h2", "text": "🛒 Cây kiểng hợp nhà bếp"}, {"type": "table", "rows": [["Cây", "Vì sao hợp"], ["Lưỡi hổ (cỡ mini)", "Chịu nóng, chịu bóng, ít tưới"], ["Lan chi", "Treo, rủ đẹp, dễ sống"], ["Trầu bà, ngọc ngân", "Chịu bóng; có thể trồng thủy sinh, không đất"], ["Ngọc bích", "Hợp bệ cửa sổ nắng"]]}, {"type": "h2", "text": "⚠️ Chỗ không nên đặt cây"}, {"type": "list", "items": ["Cạnh bếp gas, bếp từ, lò nướng, nồi cơm — nhiệt làm lá cháy, chậu nhựa biến dạng.", "Trên tủ lạnh: nóng phía trên, rung, ít sáng.", "Ngay dưới máy hút mùi: hơi dầu mỡ bám dày.", "Sát bồn rửa: nước xà phòng bắn vào đất.", "Cây có nhựa độc đặt xa chỗ chế biến thức ăn và tầm tay trẻ nhỏ."], "ordered": false}, {"type": "h2", "text": "🧽 Chăm cây trong bếp"}, {"type": "p", "text": "Lá bám dầu mỡ sẽ bí, kém quang hợp: lau lá bằng khăn ẩm 1–2 tuần một lần (xem [lau lá, cắt tỉa lá già](/goc-cham-cay/lau-la-cat-tia-cay-kieng-la)). Không lau lá bằng dầu ăn hay sữa cho bóng — làm bít lỗ khí."}, {"type": "products", "title": "Cây nhỏ cho góc bếp", "slugs": ["luoi-ho", "lan-chi", "ngoc-ngan", "ngoc-bich"]}]$j$, $j$https://live.staticflickr.com/3061/2593135672_292699fc40_b.jpg$j$, 2, '{}'::text[], ARRAY[$j$nhà bếp$j$,$j$decor$j$,$j$rau thơm$j$]::text[], $j$Chọn cây xanh cho nhà bếp: trồng rau thơm bệ cửa sổ, cây kiểng chịu nóng chịu bóng, vị trí đặt an toàn, chỗ không nên đặt và cách lau lá bám dầu mỡ.$j$, $j$2026-10-27 06:30:00+07$j$),
($j$cay-canh-cho-phong-tro-sinh-vien$j$, $j$cam-nang$j$, $j$📗 Cây cảnh cho phòng trọ, ký túc xá sinh viên: rẻ, nhỏ gọn, khó chết, ít tốn chỗ$j$, $j$Phòng trọ, ký túc xá hợp những cây nhỏ, giá mềm, chịu bóng và chịu quên tưới: lưỡi hổ mini, lan chi, ngọc ngân, dương xỉ mini, ngọc bích nếu có cửa sổ nắng. Chọn chậu có đĩa lót, đặt ở bàn học, bệ cửa sổ; về quê dài ngày thì tưới đẫm và đặt cây xa cửa sổ nắng.$j$, $j$[{"type": "p", "text": "Phòng trọ nhỏ, cửa sổ hẹp, ngân sách eo hẹp, lại hay đi học, đi làm thêm cả ngày — nhưng một chậu cây xanh trên bàn học vẫn làm góc phòng dễ chịu hơn nhiều. Bí quyết là chọn đúng loại cây \"khó chết\"."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Shelf_at_the_bottom_of_a_window_for_growing_houseplants.jpg/960px-Shelf_at_the_bottom_of_a_window_for_growing_houseplants.jpg", "caption": "Cây nhỏ trên kệ trong phòng"}, {"type": "h2", "text": "🛒 5 cây hợp phòng trọ"}, {"type": "table", "rows": [["Cây", "Vì sao hợp", "Chỗ đặt"], ["Lưỡi hổ mini", "Gần như không cần chăm, 7–10 ngày tưới", "Bàn học, góc phòng"], ["Lan chi", "Rẻ, dễ sống, ra cây con tặng bạn", "Kệ, treo cửa sổ"], ["Ngọc ngân", "Chịu bóng; trồng thủy sinh được", "Bàn học"], ["Dương xỉ mini", "Xanh mướt, an toàn thú cưng", "Cửa sổ có bóng râm, cần tưới đều"], ["Ngọc bích", "Ít tưới, sống lâu năm", "Chỉ khi có cửa sổ nắng"]]}, {"type": "h2", "text": "💡 Mẹo giữ cây trong phòng trọ"}, {"type": "list", "items": ["Chậu nhỏ phải có lỗ thoát nước và **đĩa lót** để khỏi ướt bàn, ướt sàn.", "Phòng không cửa sổ: chọn lưỡi hổ, mỗi tuần mang ra hành lang có sáng vài giờ.", "Tưới theo đất, không theo lịch — thử bằng ngón tay ([tưới cây trong nhà đúng cách](/goc-cham-cay/tuoi-cay-trong-nha-dung-cach)).", "Không đặt cây trên máy tính, tủ lạnh mini, cạnh nồi cơm điện."], "ordered": false}, {"type": "h2", "text": "🏠 Về quê dài ngày thì sao?"}, {"type": "list", "items": ["Tưới đẫm trước khi đi, đổ nước dư dưới đĩa.", "Dời cây xa cửa sổ nắng, gom các chậu lại gần nhau.", "Cây ưa ẩm: đặt trên khay sỏi có nước hoặc dùng bấc vải dẫn nước từ chai.", "Lưỡi hổ, ngọc bích chịu được 2–3 tuần không tưới."], "ordered": false}, {"type": "p", "text": "Xem chi tiết [giữ cây không chết khát khi đi vắng](/goc-cham-cay/cham-cay-khi-di-vang) và [6 cây khó chết cho người mới bắt đầu](/goc-cham-cay/cay-de-cham-cho-nguoi-moi-bat-dau)."}, {"type": "products", "title": "Cây nhỏ giá mềm", "slugs": ["lan-chi", "luoi-ho", "ngoc-ngan", "duong-xi", "duong-si"]}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Shelf_at_the_bottom_of_a_window_for_growing_houseplants.jpg/960px-Shelf_at_the_bottom_of_a_window_for_growing_houseplants.jpg$j$, 2, '{}'::text[], ARRAY[$j$phòng trọ$j$,$j$sinh viên$j$,$j$cây để bàn$j$]::text[], $j$Chọn cây cảnh cho phòng trọ, ký túc xá sinh viên: cây rẻ, nhỏ gọn, chịu bóng, chịu quên tưới; cách đặt, tưới và giữ cây khi về quê dài ngày.$j$, $j$2026-10-27 12:00:00+07$j$),
($j$cay-tang-nguoi-lon-tuoi-mung-tho$j$, $j$phong-thuy$j$, $j$🍀 Tặng cây cho người lớn tuổi, mừng thọ ông bà cha mẹ: chọn cây ý nghĩa mà dễ chăm$j$, $j$Cây tặng người lớn tuổi nên vừa có ý nghĩa trường thọ, bình an vừa thật dễ chăm, không độc, không gai. Gợi ý: tùng thơm (trường thọ), vạn niên thanh (xanh tươi muôn năm), ngọc bích (sung túc), lưỡi hổ (bền bỉ). Chọn chậu vừa tầm, nhẹ, đặt được ở chỗ cụ hay ngồi, kèm vài dòng hướng dẫn tưới.$j$, $j$[{"type": "p", "text": "Một chậu cây xanh là món quà mừng thọ vừa trang nhã vừa \"sống\" — mỗi ngày ông bà nhìn cây lớn lên là nhớ người tặng. Nhưng cây tặng người lớn tuổi cần chọn kỹ hơn: ý nghĩa phải tốt, chăm phải dễ, và an toàn khi có cháu nhỏ chạy quanh."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Hue_Vietnam_Tomb-of-Emperor-Minh-Mang-03a.jpg/960px-Hue_Vietnam_Tomb-of-Emperor-Minh-Mang-03a.jpg", "caption": "Cây cảnh dáng cổ thụ — biểu tượng trường thọ. Ảnh: CEphoto, Uwe Aranas, CC BY-SA 3.0, Wikimedia Commons"}, {"type": "h2", "text": "🍀 Cây mang ý nghĩa trường thọ, bình an (theo dân gian)"}, {"type": "table", "rows": [["Cây", "Ý nghĩa dân gian", "Mức độ dễ chăm"], ["Tùng thơm", "Bền bỉ, trường thọ", "Cần nắng sáng, tưới đều"], ["Vạn niên thanh", "Xanh tươi muôn năm, sức khỏe", "Dễ; nhựa gây ngứa — đặt xa trẻ nhỏ"], ["Ngọc bích", "Sung túc, cây tiền", "Rất dễ, ít tưới, cần nắng"], ["Lưỡi hổ", "Mạnh mẽ, xua điều xấu", "Cực dễ, chịu bóng"], ["Lan ý", "Bình yên, hoa trắng thanh khiết", "Dễ; lá rũ là báo khát nước"]]}, {"type": "h2", "text": "🛒 Chọn cây theo thói quen của người nhận"}, {"type": "list", "items": ["**Ông bà hay quên tưới**: lưỡi hổ, ngọc bích — 1 tuần tưới một lần.", "**Người thích chăm cây mỗi ngày**: tùng thơm, hoa hồng chậu, mai địa thảo.", "**Nhà có sân, ban công nắng**: ngọc bích, tắc cẩm thạch (trái vàng, sung túc).", "**Ở chung cư, ít sáng**: lưỡi hổ, ngân hậu, trầu bà đế vương."], "ordered": false}, {"type": "h2", "text": "🪴 Chậu và cách trao quà"}, {"type": "list", "items": ["Chọn chậu vừa tầm, không quá nặng để người lớn tuổi dễ dời; có đĩa lót.", "Tránh cây có gai, cây lá sắc nếu cụ yếu tay, mắt kém.", "Viết kèm một tấm thiệp nhỏ: tên cây, bao lâu tưới một lần, đặt chỗ sáng hay râm.", "Đặt sẵn cây ở chỗ cụ hay ngồi uống trà, đọc báo để cụ dễ ngắm, dễ chăm."], "ordered": false}, {"type": "p", "text": "Các ý nghĩa trên là quan niệm dân gian để tham khảo. Xem thêm [chọn cây làm quà khai trương, tân gia, sinh nhật](/goc-cham-cay/chon-cay-qua-tang-khai-truong-tan-gia) và [cây cảnh an toàn cho nhà có trẻ nhỏ](/goc-cham-cay/cay-canh-an-toan-tre-nho-thu-cung)."}, {"type": "products", "title": "Cây làm quà cho người lớn tuổi", "slugs": ["tung-thom", "van-nien-thanh", "ngoc-bich", "luoi-ho", "lan-y"]}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Hue_Vietnam_Tomb-of-Emperor-Minh-Mang-03a.jpg/960px-Hue_Vietnam_Tomb-of-Emperor-Minh-Mang-03a.jpg$j$, 2, '{}'::text[], ARRAY[$j$quà tặng$j$,$j$mừng thọ$j$,$j$phong thủy$j$]::text[], $j$Chọn cây tặng người lớn tuổi, mừng thọ ông bà, cha mẹ: cây mang ý nghĩa trường thọ, bình an theo dân gian, dễ chăm, an toàn, cách chọn chậu, lời chúc kèm theo.$j$, $j$2026-10-27 19:30:00+07$j$),
($j$cham-cuc-chung-tet-ben-hoa$j$, $j$theo-mua$j$, $j$🌦️ Chăm cúc chưng Tết (cúc mâm xôi, cúc đại đóa) cho hoa bền đến hết tháng Giêng$j$, $j$Cúc chưng Tết bền lâu khi được đặt nơi có nắng sáng, thoáng gió, tưới gốc đều mỗi ngày nhưng không để úng và không tưới lên bông. Tránh đặt cạnh quạt nóng, máy lạnh hay trong phòng kín tối. Ngắt bông tàn, lá úa thường xuyên; trước Tết chọn chậu nhiều nụ chúm chím hơn là chậu đã nở bung.$j$, $j$[{"type": "p", "text": "Cúc mâm xôi vàng rực, cúc đại đóa bông to — chậu cúc gần như không thể thiếu trước sân nhà ngày Tết miền Tây. Có nhà giữ cúc tươi tới rằm tháng Giêng, có nhà mới mùng 3 đã héo. Khác biệt nằm ở vài thói quen chăm đơn giản."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/CHRYSANTHEMUM.jpg/960px-CHRYSANTHEMUM.jpg", "caption": "Chậu hoa cúc chưng Tết. Ảnh: Inchara Srinivas, CC BY-SA 4.0, Wikimedia Commons"}, {"type": "h2", "text": "🛒 Chọn chậu cúc khi mua"}, {"type": "list", "items": ["Chọn chậu có **nhiều nụ chúm chím, vài bông vừa nở** — nở dần sẽ bền suốt Tết.", "Lá xanh đậm, không vàng úa ở gốc, không có đốm trắng (phấn trắng), không có rệp ở đọt.", "Lắc nhẹ: bầu đất chắc, cây không lung lay.", "Bông nở bung hết từ chợ: đẹp nhất lúc mua nhưng mau tàn."], "ordered": false}, {"type": "h2", "text": "📍 Đặt cúc ở đâu?"}, {"type": "list", "items": ["Sân trước, hiên nhà có **nắng sáng**, thoáng gió là tốt nhất.", "Đưa vào phòng khách chưng: chỉ vài ngày rồi đem ra ngoài lại; phòng tối kín bông mau rũ.", "Tránh luồng gió nóng, máy lạnh thổi thẳng, gần bếp."], "ordered": false}, {"type": "h2", "text": "💧 Tưới cúc đúng cách"}, {"type": "list", "items": ["Tưới **gốc** mỗi ngày vào sáng sớm (ngày nắng gắt thêm chiều mát), đủ ẩm, không đọng nước.", "**Không tưới lên bông**: bông ướt dễ thâm, thối cánh.", "Đất khô kiệt một lần là lá gốc vàng, bông rũ nhanh.", "Chậu nhựa mỏng phơi nắng nóng: đặt vào chậu lớn hơn hoặc che thành chậu."], "ordered": false}, {"type": "h2", "text": "✂️ Ngắt bông tàn, lá úa"}, {"type": "p", "text": "Mỗi ngày dạo qua ngắt bông đã tàn, lá vàng ở gốc — chậu luôn gọn đẹp, ít nấm bệnh, cây dồn sức cho nụ còn lại. Thấy rệp ở đọt thì xịt nước hoặc ngắt bỏ (xem [rệp muội](/benh-cay/rep-muoi)); đốm bột trắng trên lá là [phấn trắng](/benh-cay/phan-trang)."}, {"type": "h2", "text": "🌱 Có cần bón phân không?"}, {"type": "p", "text": "Cúc mua về đã được nhà vườn bón đủ cho đợt hoa. Trong Tết chỉ cần tưới đều; bón thêm phân đạm lúc này còn làm cây ra lá, bông kém bền."}, {"type": "h2", "text": "❓ Sau Tết giữ cúc được không?"}, {"type": "p", "text": "Được với người kiên nhẫn: cắt bỏ hết bông tàn, cắt thấp cây, bón phân hữu cơ, đặt nơi nắng — cây ra chồi mới, có thể giâm ngọn làm cây con. Nhưng cúc Tết của nhà vườn được xử lý ánh sáng để nở đúng dịp, năm sau tự trồng thường nở không đúng Tết."}, {"type": "p", "text": "Xem thêm [chuẩn bị cây cảnh đón Tết](/goc-cham-cay/chuan-bi-cay-canh-don-tet) và [chăm cây sau Tết](/goc-cham-cay/cham-cay-sau-tet)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/CHRYSANTHEMUM.jpg/960px-CHRYSANTHEMUM.jpg$j$, 2, ARRAY[$j$phan-trang$j$,$j$rep-muoi$j$]::text[], ARRAY[$j$hoa cúc$j$,$j$hoa Tết$j$,$j$cây Tết$j$]::text[], $j$Cách chăm cúc mâm xôi, cúc đại đóa chưng Tết cho hoa bền lâu: chọn chậu khi mua, vị trí đặt, cách tưới, ngắt bông tàn, xử lý lá vàng và giữ cây sau Tết.$j$, $j$2026-10-28 06:30:00+07$j$),
($j$kien-bo-tren-cay-canh-co-hai-khong$j$, $j$bat-benh$j$, $j$🐛 Kiến bò đầy cây cảnh, chậu cây: kiến có hại không và vì sao có kiến thì thường có rệp?$j$, $j$Kiến tự nó ít ăn cây, nhưng kiến bò lên cây nhiều thường là dấu hiệu cây có rệp, rệp sáp hoặc bọ phấn: kiến "chăn nuôi" chúng để lấy mật ngọt và còn bảo vệ chúng khỏi thiên địch. Muốn hết kiến phải diệt rệp trước, sau đó chặn đường kiến lên cây và xử lý tổ trong chậu.$j$, $j$[{"type": "p", "text": "Nhiều người thấy kiến bò lên xuống thân cây liền đi tìm thuốc diệt kiến. Nhưng kiến thường chỉ là \"người đưa tin\": lần theo đường kiến lên tới đọt non, mặt dưới lá, bạn sẽ thấy thủ phạm thật — rệp."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/9/9f/Ants_tending_aphids%2C_Julie_Metz_Wetlands%2C_Woodbridge%2C_Virginia.jpg", "caption": "Kiến chăm sóc đàn rệp trên thân cây để lấy mật. Ảnh: Judy Gallagher, CC BY 2.0, Wikimedia Commons"}, {"type": "h2", "text": "🔎 Vì sao có kiến thì thường có rệp?"}, {"type": "p", "text": "[Rệp muội](/benh-cay/rep-muoi), [rệp sáp](/benh-cay/rep-sap), bọ phấn hút nhựa cây và thải ra **mật ngọt**. Kiến rất thích mật này nên chúng \"chăn\" rệp: tha rệp lên đọt non, đuổi bọ rùa và ong ký sinh — kẻ thù tự nhiên của rệp. Kết quả là rệp càng đông, cây càng yếu, lá dính mật rồi đen [muội](/benh-cay/muoi-den)."}, {"type": "h2", "text": "🔍 Kiến có trực tiếp hại cây không?"}, {"type": "list", "items": ["Phần lớn kiến không ăn lá cây.", "Kiến làm tổ trong chậu làm đất rỗng, khô nhanh, rễ có chỗ bị hở; cây chậu nhỏ có thể héo.", "Vài loài kiến cắn nụ hoa, hạt giống mới gieo.", "Kiến lửa làm tổ trong chậu đặt sân vườn có thể đốt người khi tưới cây."], "ordered": false}, {"type": "h2", "text": "🛠️ Cách xử lý kiến và rệp"}, {"type": "list", "items": ["**Diệt rệp trước**: xịt nước mạnh, cắt đọt bị nặng, lau rệp sáp bằng tăm bông nhúng cồn (xem [trị rệp sáp](/goc-cham-cay/tri-rep-sap-cay-kieng-la)). Hết mật, kiến tự bỏ đi.", "**Chặn đường lên cây**: quấn một vòng băng keo hai mặt quanh thân hoặc chân kệ; đặt chân kệ chậu vào chén nước.", "**Tổ kiến trong chậu**: ngâm cả chậu vào xô nước ngập mặt đất 20–30 phút, kiến sẽ bò lên, gạt bỏ; với cây chịu úng kém thì nên thay đất mới.", "**Quanh nhà**: dùng bả kiến dạng gel đặt ở đường kiến đi (ngoài chậu, xa tầm tay trẻ nhỏ và thú cưng) để kiến mang về diệt cả tổ."], "ordered": true}, {"type": "note", "title": "⚠️ Lưu ý an toàn", "text": "Bả kiến, thuốc diệt côn trùng phải đặt xa tầm với trẻ nhỏ, chó mèo, không rắc trực tiếp vào chậu rau ăn. Rửa tay sau khi dùng."}, {"type": "h2", "text": "🛡️ Phòng kiến quay lại"}, {"type": "p", "text": "Kiểm tra đọt non mỗi tuần để diệt rệp từ khi mới có vài con; không bón dư đạm làm đọt non mập mềm; kê chậu lên kệ, không để chậu sát tường nhiều kiến."}]$j$, $j$https://upload.wikimedia.org/wikipedia/commons/9/9f/Ants_tending_aphids%2C_Julie_Metz_Wetlands%2C_Woodbridge%2C_Virginia.jpg$j$, 2, ARRAY[$j$rep-muoi$j$,$j$rep-sap$j$,$j$muoi-den$j$]::text[], ARRAY[$j$kiến$j$,$j$rệp$j$,$j$sâu hại$j$]::text[], $j$Kiến bò lên cây cảnh, làm tổ trong chậu có hại không? Vì sao kiến đi kèm rệp, rệp sáp; cách diệt rệp, chặn kiến và xử lý tổ kiến trong chậu an toàn.$j$, $j$2026-10-28 19:30:00+07$j$),
($j$cay-bi-vong-vuon-dai-la-thua$j$, $j$cham-soc$j$, $j$🌿 Cây bị vống, vươn dài, thân ốm, lá thưa: nguyên nhân do thiếu sáng và cách sửa dáng cây$j$, $j$Cây vống — thân vươn dài, ốm yếu, khoảng cách giữa các lá xa nhau, nghiêng hẳn về phía cửa sổ — gần như luôn do thiếu ánh sáng, đôi khi kèm bón dư đạm. Phần đã vống không co lại được: dời cây ra chỗ sáng hơn, xoay chậu đều, cắt ngọn cho cây bật nhánh mới và đem ngọn đi giâm.$j$, $j$[{"type": "p", "text": "Mua về cây tán tròn, gọn; vài tháng sau thân cao lêu khêu, lá thưa thớt, ngọn ngả hẳn về phía cửa sổ. Hiện tượng này gọi là **cây vống** — cây đang \"rướn người\" đi tìm ánh sáng."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Etiolation_of_plants.JPG/960px-Etiolation_of_plants.JPG", "caption": "Cây con vươn dài vì thiếu sáng. Ảnh: சஞ்சீவி சிவகுமார், CC BY-SA 4.0, Wikimedia Commons"}, {"type": "h2", "text": "🔍 Dấu hiệu cây bị vống"}, {"type": "list", "items": ["Khoảng cách giữa hai lá (đốt thân) dài ra rõ rệt so với phần thân cũ.", "Thân mảnh, mềm, dễ ngả đổ.", "Lá mới nhỏ hơn, nhạt màu; cây lá màu (phú quý, vạn lộc) xanh dần.", "Cả cây nghiêng về phía nguồn sáng.", "Cây mọng nước (ngọc bích, sen đá) dài ngoằng, lá thưa và cong xuống."], "ordered": false}, {"type": "h2", "text": "🔎 Vì sao cây bị vống?"}, {"type": "p", "text": "**Thiếu ánh sáng** là nguyên nhân chính. Cây đặt sâu trong phòng, xa cửa sổ, hay chỉ có đèn trần sẽ vươn dài để tìm sáng. Bón nhiều đạm khi cây thiếu sáng làm cây vống nhanh hơn. Cây con gieo hạt để chỗ râm cũng vống ngay trong vài ngày. Xem cách đánh giá ánh sáng trong nhà ở bài [ánh sáng cho cây trong nhà](/goc-cham-cay/anh-sang-cho-cay-trong-nha)."}, {"type": "h2", "text": "🛠️ Cách sửa cây bị vống"}, {"type": "list", "items": ["**Dời ra chỗ sáng hơn** — từ từ trong 1 tuần, không đưa thẳng ra nắng gắt (lá quen bóng sẽ cháy).", "**Xoay chậu 1/4 vòng mỗi tuần** để cây mọc thẳng, đều tán.", "**Cắt ngọn**: cắt phần thân vống phía trên một mắt lá; cây sẽ bật nhánh mới ở các mắt bên dưới, tán dày lại.", "**Đem ngọn đi giâm** để có thêm cây (xem [nhân giống cây cảnh tại nhà](/goc-cham-cay/nhan-giong-cay-canh-tai-nha)).", "**Giảm phân đạm** cho tới khi cây được đủ sáng.", "Thân quá dài không chịu nổi: cắm cọc đỡ tạm."], "ordered": true}, {"type": "p", "text": "Lưu ý: phần thân đã vống **không ngắn lại được**. Sửa đúng thì phần lá mới ra sẽ dày, đẹp; phần cũ cắt dần khi cây đã có tán mới."}, {"type": "h2", "text": "🛒 Chỗ ít sáng thì chọn cây gì?"}, {"type": "p", "text": "Nếu không thể dời chỗ, hãy chọn cây chịu bóng thật sự: [lưỡi hổ](/san-pham/luoi-ho), [ngân hậu](/san-pham/ngan-hau), [bạch mã](/san-pham/bach-ma-hoang-tu), [trầu bà đế vương xanh](/san-pham/trau-ba-de-vuong-xanh). Xem thêm [6 cây sống khỏe ở góc tối](/goc-cham-cay/cay-trong-nha-thieu-sang)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Etiolation_of_plants.JPG/960px-Etiolation_of_plants.JPG$j$, 2, '{}'::text[], ARRAY[$j$cây vống$j$,$j$thiếu sáng$j$,$j$cắt tỉa$j$]::text[], $j$Cây bị vống, vươn dài, thân ốm, lá thưa là do đâu? Nguyên nhân thiếu sáng, bón dư đạm; cách dời chỗ, xoay chậu, cắt ngọn sửa dáng cây cảnh và cây con.$j$, $j$2026-10-29 06:30:00+07$j$),
($j$trong-sa-trong-chau$j$, $j$rau-sach$j$, $j$🥬 Trồng sả trong chậu, thùng xốp từ cây sả mua chợ: ra rễ, chăm sóc và thu hoạch cả năm$j$, $j$Sả trồng rất dễ từ chính cây sả mua ngoài chợ: chọn tép còn gốc, ngâm nước 1–2 tuần cho ra rễ rồi trồng vào chậu đất tơi, nơi đủ nắng. Sả chịu hạn, ít sâu bệnh, chỉ cần tưới khi đất khô và bón ít phân. Sau 2–3 tháng có thể cắt dùng, bụi sả ngày càng to.$j$, $j$[{"type": "p", "text": "Sả là gia vị không thể thiếu trong bếp miền Tây: kho, xào, nướng, nấu nước. Trồng một chậu sả ở ban công vừa có sả tươi dùng quanh năm, vừa được tiếng là giúp đuổi muỗi (mùi sả có tác dụng nhẹ, không thay được biện pháp diệt muỗi)."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Tanglad_%28lemongrass%2C_Cymbopogon_citratus%29_-_Philippines.jpg/960px-Tanglad_%28lemongrass%2C_Cymbopogon_citratus%29_-_Philippines.jpg", "caption": "Bụi sả trồng chậu"}, {"type": "h2", "text": "🌱 Cho sả ra rễ từ cây mua chợ"}, {"type": "list", "items": ["Chọn cây sả tươi, còn nguyên phần gốc dưới (đáy tép), không bị cắt sát.", "Cắt bớt lá, chừa thân dài 15–20cm.", "Cắm gốc vào ly nước ngập 3–4cm, đặt nơi sáng, thay nước 2–3 ngày một lần.", "Sau 1–2 tuần rễ trắng mọc dài 2–3cm là đem trồng."], "ordered": true}, {"type": "h2", "text": "🪴 Chậu, đất và chỗ đặt"}, {"type": "list", "items": ["Chậu hoặc thùng sâu ít nhất 25–30cm — bụi sả lớn nhanh, rễ nhiều.", "Đất tơi thoát nước, trộn ít phân hữu cơ.", "Nắng nhiều càng tốt, ít nhất 5–6 giờ/ngày.", "Trồng mỗi chậu 3–5 tép, cách nhau 10cm."], "ordered": false}, {"type": "h2", "text": "💧 Tưới và bón"}, {"type": "list", "items": ["Mới trồng: giữ ẩm 1–2 tuần cho bén rễ.", "Sau đó tưới khi mặt đất khô; sả chịu hạn tốt, sợ úng.", "1–2 tháng một lần rắc phân trùn quế hoặc phân hữu cơ quanh gốc."], "ordered": false}, {"type": "h2", "text": "✂️ Thu hoạch và tách bụi"}, {"type": "p", "text": "Sau 2–3 tháng, bụi đã đẻ thêm nhiều tép. Cắt sát gốc những tép to bên ngoài, chừa tép non ở giữa. Bụi quá dày, chật chậu thì nhấc ra tách thành nhiều bụi nhỏ trồng sang chậu khác. Lá sả già có thể cắt bớt để bụi thoáng (đeo găng vì mép lá sắc)."}, {"type": "p", "text": "Xem thêm [trồng hành lá tại nhà từ gốc hành](/goc-cham-cay/trong-hanh-la-tai-nha) và [trồng rau thơm ban công](/goc-cham-cay/trong-rau-thom-ban-cong)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Tanglad_%28lemongrass%2C_Cymbopogon_citratus%29_-_Philippines.jpg/960px-Tanglad_%28lemongrass%2C_Cymbopogon_citratus%29_-_Philippines.jpg$j$, 2, '{}'::text[], ARRAY[$j$sả$j$,$j$rau gia vị$j$,$j$trồng chậu$j$]::text[], $j$Cách trồng sả trong chậu, thùng xốp tại nhà từ sả mua chợ: cách cho ra rễ, chọn chậu, đất, tưới, bón, tách bụi và thu hoạch sả quanh năm.$j$, $j$2026-10-29 12:00:00+07$j$),
($j$dau-neem-xa-phong-sinh-hoc-tri-sau$j$, $j$thuoc-phan-bon$j$, $j$🧪 Dầu neem và xà phòng sinh học trị rệp, nhện, bọ phấn: pha thế nào, phun ra sao cho an toàn$j$, $j$Dầu neem và xà phòng sinh học (xà phòng kali) trị được rệp, rệp sáp non, nhện, bọ phấn khi phun trúng con. Chúng ít độc, hợp cây trong nhà và rau, nhưng phải pha đúng tỉ lệ ghi trên chai, thử trước trên vài lá, phun lúc chiều mát, phun kỹ mặt dưới lá và lặp lại sau 5–7 ngày.$j$, $j$[{"type": "p", "text": "Với cây trồng trong nhà, trên ban công hay rau ăn hằng ngày, nhiều người muốn tránh thuốc hóa học mạnh. Dầu neem và xà phòng sinh học là hai lựa chọn phổ biến — hiệu quả với côn trùng nhỏ thân mềm nếu dùng đúng cách."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Azadirachta_indica%2C_leaves_%26_fruits.JPG/960px-Azadirachta_indica%2C_leaves_%26_fruits.JPG", "caption": "Lá cây neem (xoan Ấn Độ). Ảnh: Kevinsooryan, CC BY-SA 3.0, Wikimedia Commons"}, {"type": "h2", "text": "📖 Dầu neem là gì?"}, {"type": "p", "text": "Dầu neem ép từ hạt cây neem (xoan Ấn Độ). Hoạt chất trong dầu làm côn trùng chán ăn, rối loạn lột xác; lớp dầu cũng làm con non bị bít thở. Tác dụng chậm hơn thuốc hóa học — vài ngày mới thấy rệp giảm rõ."}, {"type": "h2", "text": "🧼 Xà phòng sinh học là gì?"}, {"type": "p", "text": "Là xà phòng gốc axit béo (xà phòng kali) làm tan lớp sáp bảo vệ của côn trùng thân mềm. **Chỉ có tác dụng khi phun trúng con**, khô rồi là hết tác dụng. Không dùng nước rửa chén, xà phòng giặt thay thế — nhiều loại có chất tẩy, hương liệu làm cháy lá."}, {"type": "h2", "text": "🐛 Trị được những gì?"}, {"type": "table", "rows": [["Đối tượng", "Hiệu quả"], ["Rệp muội, bọ phấn", "Tốt khi phun kỹ, lặp lại"], ["Nhện đỏ", "Khá; phải phun mặt dưới lá"], ["Rệp sáp non", "Khá; con già có lớp sáp dày cần lau bằng cồn trước"], ["Bọ trĩ", "Trung bình"], ["Sâu to, ốc sên", "Kém — nên bắt tay"]]}, {"type": "h2", "text": "🛠️ Cách pha và phun"}, {"type": "list", "items": ["Pha **đúng tỉ lệ ghi trên chai** sản phẩm; dầu neem cần chất nhũ hóa đi kèm mới hòa được với nước.", "Thử trước trên 2–3 lá, chờ 24 giờ không cháy mới phun cả cây.", "Phun lúc **chiều mát**, không phun khi nắng gắt (lá dính dầu dưới nắng dễ cháy).", "Phun ướt đều **mặt dưới lá**, nách lá, đọt non — nơi côn trùng trú.", "Lặp lại 5–7 ngày một lần, 3–4 lần, để diệt lứa mới nở từ trứng.", "Pha xong dùng hết trong ngày."], "ordered": true}, {"type": "note", "title": "⚠️ Lưu ý an toàn", "text": "Dầu neem và xà phòng sinh học ít độc nhưng vẫn là sản phẩm bảo vệ thực vật: đọc nhãn, đeo găng tay, tránh mắt, để xa tầm tay trẻ nhỏ, không phun lên hoa đang có ong bướm ghé. Với rau, rửa kỹ trước khi ăn và tuân thủ thời gian cách ly ghi trên nhãn. Xem [hướng dẫn dùng thuốc an toàn](/chinh-sach/thuoc-bvtv-an-toan)."}, {"type": "p", "text": "Xem thêm [nhện đỏ mùa khô](/goc-cham-cay/nhen-do-mua-kho-cay-canh), [rệp sáp trên cây kiểng lá](/goc-cham-cay/tri-rep-sap-cay-kieng-la) và [đọc nhãn thuốc trước khi dùng](/goc-cham-cay/doc-nhan-thuoc-bvtv-truoc-khi-dung)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Azadirachta_indica%2C_leaves_%26_fruits.JPG/960px-Azadirachta_indica%2C_leaves_%26_fruits.JPG$j$, 2, ARRAY[$j$rep-muoi$j$,$j$rep-sap$j$,$j$nhen-do$j$,$j$bo-tri$j$]::text[], ARRAY[$j$dầu neem$j$,$j$thuốc sinh học$j$,$j$rệp$j$,$j$nhện đỏ$j$]::text[], $j$Cách dùng dầu neem và xà phòng sinh học trị rệp, nhện đỏ, bọ phấn trên cây cảnh, rau: pha đúng tỉ lệ, thử lá, thời điểm phun, số lần phun và lưu ý an toàn.$j$, $j$2026-10-29 19:30:00+07$j$),
($j$lam-tieu-canh-terrarium-binh-thuy-tinh$j$, $j$decor$j$, $j$🏡 Tự làm tiểu cảnh terrarium trong bình thủy tinh: chọn bình, xếp lớp đất và cây cho bền đẹp$j$, $j$Terrarium là tiểu cảnh cây trồng trong bình thủy tinh. Làm đúng 4 lớp từ dưới lên: sỏi thoát nước, than hoạt tính, rêu hoặc lưới ngăn, giá thể; chọn cây nhỏ cùng nhu cầu nước. Bình kín hợp cây ưa ẩm như dương xỉ nhỏ, rêu; bình hở hợp sen đá, xương rồng. Đặt nơi sáng tán xạ, không nắng chiếu thẳng.$j$, $j$[{"type": "p", "text": "Một khu vườn thu nhỏ trong chiếc bình thủy tinh trên bàn làm việc — terrarium là món decor được nhiều bạn trẻ thích tự tay làm. Làm đúng nguyên tắc, tiểu cảnh có thể sống nhiều tháng tới nhiều năm."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Terrarium_small.jpg/960px-Terrarium_small.jpg", "caption": "Tiểu cảnh terrarium trong bình thủy tinh. Ảnh: christopher*, CC BY 2.0, Wikimedia Commons"}, {"type": "h2", "text": "🛒 Chọn bình kín hay bình hở?"}, {"type": "table", "rows": [["Loại bình", "Đặc điểm", "Cây hợp"], ["Bình kín (có nắp)", "Hơi nước tuần hoàn, rất ẩm, ít phải tưới", "Rêu, dương xỉ nhỏ, cây lá nhỏ ưa ẩm"], ["Bình hở (miệng rộng)", "Thoáng, khô nhanh", "Sen đá, xương rồng, cây mọng nước"]]}, {"type": "p", "text": "**Không trộn** cây ưa ẩm với cây mọng nước trong cùng một bình — một bên sẽ chết."}, {"type": "h2", "text": "📝 Xếp lớp từ dưới lên"}, {"type": "list", "items": ["**Sỏi nhỏ, đá cuội** dày 2–3cm: chỗ chứa nước dư (bình không có lỗ thoát).", "**Than hoạt tính** một lớp mỏng: hạn chế mùi, nấm mốc.", "**Rêu khô hoặc lưới mỏng**: ngăn đất lọt xuống sỏi.", "**Giá thể**: bình kín dùng đất tơi giàu mùn; bình hở dùng giá thể nhiều cát, sỏi nhỏ.", "Trồng cây, phủ rêu, đá, sỏi màu, tượng nhỏ trang trí."], "ordered": true}, {"type": "h2", "text": "🌿 Trồng cây"}, {"type": "list", "items": ["Chọn cây nhỏ, lớn chậm; rũ bớt đất bầu, tỉa rễ dài.", "Dùng nhíp dài, đũa để đặt cây qua miệng bình hẹp.", "Chừa khoảng trống giữa cây và thành bình để lá không dính kính (dễ thối)."], "ordered": false}, {"type": "h2", "text": "💧 Tưới và chăm"}, {"type": "list", "items": ["Bình kín: tưới phun sương nhẹ lúc mới làm; sau đó chỉ tưới khi thành bình không còn đọng hơi nước nhiều ngày. Hơi nước đọng dày cả ngày = quá ẩm, mở nắp vài giờ.", "Bình hở: tưới bằng muỗng hoặc ống nhỏ giọt quanh gốc, 1–2 tuần một lần.", "Ánh sáng tán xạ; **nắng chiếu thẳng vào bình làm cây \"luộc chín\"** trong vài giờ.", "Lá vàng, mốc: gắp bỏ ngay, mở nắp cho thoáng."], "ordered": false}, {"type": "h2", "text": "❓ Vì sao terrarium bị mốc, thối?"}, {"type": "p", "text": "Thường do tưới quá nhiều, thiếu lớp sỏi thoát nước, hoặc dùng đất chưa sạch. Xem thêm [thối rễ](/benh-cay/thoi-re) và [đốm lá do nấm](/benh-cay/dom-la-nam)."}, {"type": "p", "text": "Xem thêm [trang trí kệ sách, kệ tivi bằng cây xanh](/goc-cham-cay/trang-tri-ke-sach-bang-cay) và [tạo góc xanh cho bàn làm việc tại nhà](/goc-cham-cay/goc-xanh-ban-lam-viec-tai-nha)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Terrarium_small.jpg/960px-Terrarium_small.jpg$j$, 2, ARRAY[$j$thoi-re$j$,$j$dom-la-nam$j$]::text[], ARRAY[$j$terrarium$j$,$j$tiểu cảnh$j$,$j$decor$j$]::text[], $j$Cách tự làm tiểu cảnh terrarium bình thủy tinh tại nhà: chọn bình kín hay hở, xếp lớp sỏi, than, đất, chọn cây phù hợp, tưới và chăm cho bền đẹp.$j$, $j$2026-10-30 06:30:00+07$j$),
($j$cay-trong-phong-khong-cua-so$j$, $j$cam-nang$j$, $j$📗 Phòng không có cửa sổ trồng cây gì sống được? 5 cây chịu tối nhất và cách giữ cây khỏe$j$, $j$Phòng không cửa sổ hầu như không có ánh sáng tự nhiên, nên chỉ cây chịu bóng mạnh như lưỡi hổ, ngân hậu, bạch mã, trầu bà đế vương xanh mới trụ được — và vẫn cần đèn bật đủ 8–10 giờ mỗi ngày hoặc luân phiên mang ra chỗ sáng. Tưới ít hơn bình thường vì đất khô chậm.$j$, $j$[{"type": "p", "text": "Phòng làm việc giữa tòa nhà, phòng ngủ ngăn vách, quầy lễ tân không có cửa sổ — đây là môi trường khó nhất cho cây. Nói thẳng: **không cây nào sống lâu dài trong bóng tối hoàn toàn**. Nhưng với đèn và lựa chọn đúng, vẫn có cây trụ được và đẹp."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Young_snake_plant_%28Sansevieria%29_in_pot.jpg/960px-Young_snake_plant_%28Sansevieria%29_in_pot.jpg", "caption": "Cây trong phòng dưới ánh đèn"}, {"type": "h2", "text": "🛒 5 cây chịu tối tốt nhất"}, {"type": "table", "rows": [["Cây", "Ghi chú"], ["Lưỡi hổ", "Chịu tối và chịu khô bậc nhất; tưới rất thưa"], ["Ngân hậu", "Lá bạc, chịu bóng rất tốt"], ["Bạch mã", "Chịu bóng, dáng thẳng sang"], ["Trầu bà đế vương xanh", "Lá to, bền, chịu bóng"], ["Ngọc ngân", "Nhỏ gọn, có thể trồng thủy sinh"]]}, {"type": "p", "text": "Cây lá màu đỏ, cây ra hoa, cây mọng nước ưa nắng (ngọc bích, sen đá) **không hợp** phòng không cửa sổ."}, {"type": "h2", "text": "💡 Ánh đèn có đủ không?"}, {"type": "list", "items": ["Đèn trần văn phòng bật 8–10 giờ/ngày đủ cho cây chịu bóng mạnh đặt gần đèn.", "Phòng ngủ chỉ bật đèn buổi tối: không đủ — cần đèn LED trồng cây hẹn giờ.", "Xem cách chọn và đặt đèn ở bài [ánh sáng cho cây trong nhà](/goc-cham-cay/anh-sang-cho-cay-trong-nha)."], "ordered": false}, {"type": "h2", "text": "🔄 Luân phiên cây"}, {"type": "p", "text": "Cách nhiều văn phòng dùng: có 2 bộ cây, mỗi 1–2 tuần đổi một bộ ra chỗ sáng (hành lang, ban công) và đưa bộ kia vào. Cây được \"nạp năng lượng\" nên giữ màu lá lâu hơn hẳn."}, {"type": "h2", "text": "💧 Tưới ít hơn bình thường"}, {"type": "p", "text": "Không có nắng, đất khô rất chậm. Tưới theo kiểu chỗ sáng là cây úng rễ nhanh — chỉ tưới khi mặt đất khô 2–3cm (lưỡi hổ: khô hẳn). Lá vàng từ dưới lên, đất có mùi là dấu hiệu [thối rễ](/benh-cay/thoi-re). Không bón phân nhiều — cây thiếu sáng dùng rất ít dinh dưỡng."}, {"type": "h2", "text": "🔍 Dấu hiệu cây đang thiếu sáng"}, {"type": "list", "items": ["Lá mới nhỏ dần, nhạt màu.", "Thân vươn dài, nghiêng về phía đèn.", "Lá già rụng dần, tán thưa."], "ordered": false}, {"type": "p", "text": "Xem thêm [cây trồng trong nhà thiếu sáng](/goc-cham-cay/cay-trong-nha-thieu-sang) và [cây văn phòng chịu bóng, ít tưới](/goc-cham-cay/cay-van-phong-chiu-bong-it-tuoi)."}, {"type": "products", "title": "Cây chịu tối tại vườn", "slugs": ["luoi-ho", "ngan-hau", "bach-ma-hoang-tu", "trau-ba-de-vuong-xanh", "ngoc-ngan"]}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Young_snake_plant_%28Sansevieria%29_in_pot.jpg/960px-Young_snake_plant_%28Sansevieria%29_in_pot.jpg$j$, 2, ARRAY[$j$thoi-re$j$]::text[], ARRAY[$j$phòng không cửa sổ$j$,$j$cây chịu bóng$j$,$j$cây văn phòng$j$]::text[], $j$Phòng không có cửa sổ trồng cây gì? 5 cây chịu tối: lưỡi hổ, ngân hậu, bạch mã, trầu bà đế vương, ngọc ngân; cách dùng đèn, luân phiên và tưới để cây sống khỏe.$j$, $j$2026-10-30 19:30:00+07$j$),
($j$ruoi-nho-bay-quanh-chau-cay$j$, $j$bat-benh$j$, $j$🐛 Ruồi nhỏ li ti bay quanh chậu cây trong nhà: đó là ruồi nấm đất — nguyên nhân và cách hết hẳn$j$, $j$Ruồi đen nhỏ li ti bay quanh chậu cây trong nhà thường là ruồi nấm đất: chúng đẻ trứng trong đất ẩm, giàu mùn. Con trưởng thành chỉ gây phiền, nhưng ấu trùng ăn rễ non. Cách hết: để mặt đất khô 2–3cm giữa hai lần tưới, đặt bẫy dính vàng, phủ lớp cát hoặc sỏi lên mặt chậu.$j$, $j$[{"type": "p", "text": "Cây kiểng trong phòng khách tự nhiên có cả đám ruồi đen nhỏ như muỗi, bay lởn vởn quanh chậu và cả quanh màn hình máy tính. Đây là **ruồi nấm đất** (fungus gnat) — gần như lúc nào cũng báo hiệu một điều: **đất chậu đang quá ẩm**."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Dark-winged_Fungus_Gnat_%288009220744%29.jpg/960px-Dark-winged_Fungus_Gnat_%288009220744%29.jpg", "caption": "Ruồi nấm đất trưởng thành — nhỏ, đen, chân dài như muỗi. Ảnh: John Tann from Sydney, Australia, CC BY 2.0, Wikimedia Commons"}, {"type": "h2", "text": "🔍 Nhận biết ruồi nấm đất"}, {"type": "list", "items": ["Ruồi nhỏ 2–3mm, màu đen xám, chân dài, bay chậm, hay đậu trên mặt đất chậu.", "Tưới nước xong, chúng bay lên từ mặt đất.", "Ấu trùng là con dòi trắng nhỏ, đầu đen, sống ở lớp đất mặt 2–5cm.", "Khác ruồi giấm (thân nâu vàng, mắt đỏ, bay quanh trái cây chín)."], "ordered": false}, {"type": "h2", "text": "🔎 Ruồi nấm đất có hại cây không?"}, {"type": "p", "text": "Con trưởng thành chỉ gây phiền. Ấu trùng ăn nấm, mùn trong đất, nhưng khi đông chúng ăn cả **rễ non, hom giâm, cây con mới gieo**, làm cây con đổ rạp. Đất ẩm kéo dài cũng là điều kiện dẫn tới [thối rễ](/benh-cay/thoi-re) — nên ruồi nấm là lời nhắc bạn đang tưới quá tay."}, {"type": "h2", "text": "🛠️ Cách diệt ruồi nấm đất"}, {"type": "list", "items": ["**Để đất khô lớp mặt**: chờ mặt đất khô 2–3cm rồi mới tưới. Ấu trùng chết khi lớp đất mặt khô. Đây là bước quan trọng nhất (xem [tưới cây trong nhà đúng cách](/goc-cham-cay/tuoi-cay-trong-nha-dung-cach)).", "**Bẫy dính màu vàng** cắm trên mặt chậu để bắt con trưởng thành, cắt đứt vòng đẻ trứng.", "**Tưới từ đáy**: đặt chậu vào khay nước 15–20 phút cho đất hút từ dưới lên, mặt đất luôn khô hơn.", "**Phủ mặt chậu** lớp cát, sỏi nhỏ hoặc đá trang trí dày 1–2cm, ruồi khó đẻ trứng xuống đất.", "Bỏ lá rụng, xác hoa trên mặt chậu; đổ nước đọng dưới đĩa.", "Đất mục, có mùi hôi: thay đất mới thoát nước tốt."], "ordered": true}, {"type": "p", "text": "Thường sau 2–3 tuần giữ đất khô mặt và đặt bẫy, đám ruồi giảm hẳn."}, {"type": "h2", "text": "🛡️ Phòng ruồi nấm"}, {"type": "p", "text": "Dùng giá thể thoát nước (xơ dừa, trấu hun, đá perlite) thay vì đất thịt nặng ([tự trộn đất](/goc-cham-cay/tron-dat-trong-cay-kieng-la)); không dùng phân hữu cơ chưa hoai trong chậu để trong nhà; chậu có lỗ thoát nước."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Dark-winged_Fungus_Gnat_%288009220744%29.jpg/960px-Dark-winged_Fungus_Gnat_%288009220744%29.jpg$j$, 2, ARRAY[$j$thoi-re$j$]::text[], ARRAY[$j$ruồi nấm đất$j$,$j$cây trong nhà$j$,$j$sâu hại$j$]::text[], $j$Ruồi nhỏ, muỗi đen bay quanh chậu cây trong nhà là ruồi nấm đất. Nguyên nhân do đất ẩm, cách diệt bằng để đất khô, bẫy dính vàng, phủ cát và phòng tái phát.$j$, $j$2026-10-31 06:30:00+07$j$),
($j$den-led-trong-cay-trong-nha$j$, $j$cham-soc$j$, $j$💡 Đèn LED trồng cây trong nhà: khi nào cần, chọn loại nào và bật bao nhiêu giờ mỗi ngày$j$, $j$Đèn LED trồng cây giúp cây trong phòng không cửa sổ hoặc góc tối sống khỏe hơn. Với cây kiểng lá, một bóng LED ánh trắng toàn phổ đặt cách ngọn 30–60cm, bật 10–12 giờ mỗi ngày bằng ổ cắm hẹn giờ là đủ. Đèn tím hồng chuyên dụng không bắt buộc và khó chịu cho mắt khi đặt trong phòng ở.$j$, $j$[{"type": "p", "text": "Phòng ngủ không cửa sổ, quầy lễ tân sâu trong tòa nhà, kệ sách góc tối — những chỗ đó đèn trần thường không đủ cho cây. Một bóng đèn LED trồng cây có thể biến chỗ \"cây nào cũng chết\" thành chỗ trồng được."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/LED_panel_and_plants.jpg/960px-LED_panel_and_plants.jpg", "caption": "Cây trồng dưới đèn LED trong nhà"}, {"type": "h2", "text": "🔎 Khi nào cần đèn trồng cây?"}, {"type": "list", "items": ["Phòng không có cửa sổ hoặc cửa sổ bị che hoàn toàn.", "Cây đặt cách cửa sổ trên 3m.", "Cây đã vống, lá nhạt dần dù tưới bón đúng (xem [ánh sáng cho cây trong nhà](/goc-cham-cay/anh-sang-cho-cay-trong-nha)).", "Muốn trồng cây ưa sáng (sen đá, ngọc bích, rau thơm) trong nhà."], "ordered": false}, {"type": "h2", "text": "🛒 Chọn đèn nào?"}, {"type": "table", "rows": [["Loại đèn", "Ưu điểm", "Nhược điểm"], ["LED trắng toàn phổ (full spectrum)", "Ánh sáng tự nhiên, dễ nhìn, hợp phòng ở", "Cường độ có hạn với bóng nhỏ"], ["LED tím hồng (đỏ + xanh dương)", "Hiệu quả cao cho cây", "Ánh tím khó chịu cho mắt, nhìn màu cây sai"], ["Bóng LED trắng thường (6500K)", "Rẻ, dễ mua", "Kém hơn đèn chuyên dụng, cần đặt gần"]]}, {"type": "p", "text": "Với cây kiểng lá trong phòng ở, **LED trắng toàn phổ** là lựa chọn dễ chịu nhất. Đèn tím hợp kệ ươm cây con, tủ trồng rau mầm."}, {"type": "h2", "text": "📏 Đặt đèn cách cây bao xa?"}, {"type": "list", "items": ["Cây kiểng lá chịu bóng: 40–60cm từ ngọn.", "Cây ưa sáng, cây mọng nước, rau: 20–30cm.", "Lá bạc màu, cháy đốm ngay dưới đèn: đèn quá gần, nâng lên.", "Cây vẫn vươn dài về phía đèn: đèn còn xa hoặc yếu, hạ xuống."], "ordered": false}, {"type": "h2", "text": "⏱️ Bật bao nhiêu giờ mỗi ngày?"}, {"type": "p", "text": "Cây kiểng lá: **10–12 giờ/ngày**; cây ưa sáng: 12–14 giờ. Cây cần cả thời gian tối để nghỉ — đừng bật 24/24. Dùng **ổ cắm hẹn giờ** để đèn bật tắt đều đặn, không phụ thuộc trí nhớ."}, {"type": "h2", "text": "⚠️ Lưu ý an toàn"}, {"type": "list", "items": ["Chọn đèn có chứng nhận, dây điện xa chỗ tưới nước.", "Không đặt đèn sát lá — dù LED ít nóng, lá sát bóng vẫn có thể cháy.", "Cây dưới đèn khô đất nhanh hơn một chút, kiểm tra độ ẩm đất thường xuyên hơn."], "ordered": false}, {"type": "p", "text": "Muốn chọn cây ít cần sáng? Xem [cây trồng trong nhà thiếu sáng](/goc-cham-cay/cay-trong-nha-thieu-sang)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/LED_panel_and_plants.jpg/960px-LED_panel_and_plants.jpg$j$, 2, '{}'::text[], ARRAY[$j$đèn LED trồng cây$j$,$j$cây trong nhà$j$,$j$ánh sáng$j$]::text[], $j$Đèn LED trồng cây trong nhà có cần không? Cách chọn đèn trắng toàn phổ hay đèn tím, khoảng cách đặt đèn, số giờ bật mỗi ngày cho cây kiểng lá, cây mọng nước.$j$, $j$2026-10-31 19:30:00+07$j$),
($j$trong-rau-ngot-tai-nha$j$, $j$rau-sach$j$, $j$🥬 Trồng rau ngót tại nhà bằng cành giâm: làm hàng rào xanh, cắt ngọn ăn quanh năm$j$, $j$Rau ngót trồng bằng cành giâm rất dễ: chọn cành bánh tẻ dài 20–25cm, cắm nghiêng vào đất ẩm, khoảng 2–3 tuần ra lá mới. Cây ưa ẩm, chịu bóng một phần, sống nhiều năm; cắt ngọn thường xuyên để cây ra nhiều nhánh non. Có thể trồng làm hàng rào quanh sân.$j$, $j$[{"type": "p", "text": "Rau ngót nấu canh thịt bằm là món dân dã ai cũng biết. Cây sống lâu năm, càng cắt càng ra ngọn, trồng vài khóm cạnh hàng rào là gần như cả năm không phải mua rau ngót."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Sauropus_androgynous_7816.jpg/960px-Sauropus_androgynous_7816.jpg", "caption": "Khóm rau ngót. Ảnh: Vengolis, CC BY-SA 4.0, Wikimedia Commons"}, {"type": "h2", "text": "🌱 Giâm cành rau ngót"}, {"type": "list", "items": ["Chọn cành bánh tẻ (không quá non, không quá già), to bằng chiếc đũa trở lên.", "Cắt đoạn dài 20–25cm, có 4–5 mắt, tuốt bỏ lá.", "Cắm nghiêng 45° vào đất ẩm, vùi 1/2 – 2/3 chiều dài cành.", "Giữ đất ẩm, để chỗ râm nhẹ; sau 2–3 tuần cành ra chồi lá mới."], "ordered": true}, {"type": "h2", "text": "🪴 Đất, chậu, chỗ trồng"}, {"type": "list", "items": ["Trồng đất vườn hoặc thùng xốp, chậu sâu 25–30cm.", "Đất tơi, giàu mùn; trộn phân chuồng hoai khi trồng.", "Ưa nắng sáng nhưng chịu bóng một phần — hợp góc sân ít nắng.", "Trồng hàng rào: cắm cành cách nhau 15–20cm thành hàng."], "ordered": false}, {"type": "h2", "text": "💧 Tưới và bón"}, {"type": "p", "text": "Rau ngót thích đất ẩm: mùa nắng tưới mỗi ngày, mùa mưa giảm. Sau mỗi lần cắt, rắc phân hữu cơ hoặc tưới nước phân trùn quế loãng để cây nhanh ra ngọn mới."}, {"type": "h2", "text": "✂️ Thu hoạch"}, {"type": "p", "text": "Khi cây cao 40–50cm, cắt ngọn non dài 15–20cm. Mỗi lần cắt, chừa lại vài mắt để cây đâm nhánh. Định kỳ vài tháng đốn thấp toàn bộ khóm còn 30–40cm cho cây ra lứa ngọn mới mập, lá non mềm."}, {"type": "note", "title": "💡 Lưu ý khi ăn", "text": "Rau ngót là rau ăn phổ biến khi nấu chín. Không nên ăn sống, ép nước uống lượng lớn. Phụ nữ mang thai nên hỏi ý kiến bác sĩ về lượng rau ngót trong khẩu phần, theo khuyến cáo phổ biến."}, {"type": "p", "text": "Xem thêm [trồng rau muống thùng xốp](/goc-cham-cay/trong-rau-muong-thung-xop) và [ủ phân hữu cơ từ rác bếp](/goc-cham-cay/u-phan-huu-co-tu-rac-bep)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Sauropus_androgynous_7816.jpg/960px-Sauropus_androgynous_7816.jpg$j$, 2, '{}'::text[], ARRAY[$j$rau ngót$j$,$j$rau sạch$j$,$j$hàng rào$j$]::text[], $j$Cách trồng rau ngót tại nhà bằng cành giâm trong chậu, thùng hoặc làm hàng rào: chọn cành, giâm, tưới, bón, cắt tỉa và thu hoạch ngọn non quanh năm.$j$, $j$2026-11-01 06:30:00+07$j$),
($j$tro-bep-voi-bot-cho-cay-khi-nao-dung$j$, $j$thuoc-phan-bon$j$, $j$🧪 Tro bếp, vôi bột cho cây trồng: khi nào nên dùng, liều bao nhiêu và khi nào tuyệt đối không$j$, $j$Tro bếp chứa kali, canxi và làm giảm chua đất; vôi bột dùng để khử chua, cải tạo đất phèn. Cả hai chỉ nên dùng khi đất chua, với liều nhỏ, trộn đều trước khi trồng vài tuần. Không dùng cho cây ưa chua, không rải chung với phân đạm, không dùng tro than đá, tro đồ nhựa.$j$, $j$[{"type": "p", "text": "Ở miền Tây, nhiều nhà có sẵn tro bếp củi, tro trấu và quen dùng vôi để cải tạo đất phèn. Dùng đúng thì đất bớt chua, cây khỏe; dùng quá tay thì đất kiềm, cây vàng lá vì không hút được sắt."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Wood_ash.jpg/960px-Wood_ash.jpg", "caption": "Tro bếp từ củi, rơm. Ảnh: Laurentius, CC BY-SA 3.0, Wikimedia Commons"}, {"type": "h2", "text": "📖 Tro bếp có gì?"}, {"type": "list", "items": ["Chủ yếu **kali** và **canxi**, ít lân; không có đạm.", "Tính kiềm: làm giảm độ chua của đất.", "Chỉ dùng tro từ củi, rơm, trấu, lá khô. **Không dùng** tro than đá, tro đốt nhựa, giấy in màu, gỗ sơn."], "ordered": false}, {"type": "h2", "text": "📖 Vôi bột dùng làm gì?"}, {"type": "p", "text": "Vôi (vôi bột nông nghiệp, vôi dolomite) dùng để **khử chua, cải tạo đất phèn**, bổ sung canxi (dolomite có thêm magie). Vôi sống (vôi cục) nóng, ăn da — không rải trực tiếp quanh gốc cây đang sống."}, {"type": "h2", "text": "🔎 Khi nào nên dùng?"}, {"type": "list", "items": ["Đất chua, phèn: nước ruộng, mương có váng vàng đỏ, đất có mùi chua, cây chậm lớn.", "Lúc làm đất trước khi trồng — trộn vôi, tưới ẩm, chờ 2–3 tuần rồi mới trồng.", "Tro bếp rắc mỏng quanh luống rau ngoài trời để bổ sung kali, và làm vành khô ngăn [ốc sên](/benh-cay/oc-sen).", "Có bút, giấy đo pH đất thì tốt nhất: chỉ bón khi đất thật sự chua."], "ordered": false}, {"type": "h2", "text": "⚠️ Khi nào không dùng?"}, {"type": "list", "items": ["Cây ưa đất chua (nhiều loại lan, cây họ đỗ quyên) — tro, vôi làm cây vàng lá.", "Chậu cây kiểng trong nhà dùng giá thể sẵn: thường không cần.", "**Không trộn chung tro, vôi với phân đạm** (urê, phân chuồng tươi): đạm bay hơi mất tác dụng. Bón cách nhau ít nhất 1–2 tuần.", "Không rải dày sát gốc, không bón khi đất khô kiệt."], "ordered": false}, {"type": "h2", "text": "📏 Liều lượng tham khảo"}, {"type": "p", "text": "Tro bếp: một nắm nhỏ (khoảng 1–2 muỗng canh) cho chậu đường kính 30cm, vài tháng một lần; luống rau rắc mỏng như rắc muối. Vôi cải tạo đất: theo hướng dẫn trên bao, thường vài trăm gam cho mỗi mét vuông đất chua, trộn đều. Ít mà đều tốt hơn nhiều một lần."}, {"type": "note", "title": "⚠️ Lưu ý an toàn", "text": "Vôi bột và tro bếp có tính kiềm, có thể gây rát da, hại mắt. Đeo găng tay, khẩu trang khi rải, tránh ngày gió, để xa tầm tay trẻ nhỏ."}, {"type": "p", "text": "Xem thêm [phòng mặn cho cây sân vườn mùa khô](/goc-cham-cay/phong-man-cho-cay-san-vuon) và [vàng lá gân xanh do thiếu sắt](/benh-cay/vang-la-thieu-sat)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Wood_ash.jpg/960px-Wood_ash.jpg$j$, 2, ARRAY[$j$oc-sen$j$]::text[], ARRAY[$j$tro bếp$j$,$j$vôi bột$j$,$j$đất phèn$j$]::text[], $j$Dùng tro bếp, vôi bột cho cây trồng: tác dụng, khi nào nên dùng cho đất chua phèn miền Tây, liều lượng, cách bón và những trường hợp không được dùng.$j$, $j$2026-11-01 12:00:00+07$j$),
($j$nam-moc-trang-tren-mat-dat-chau$j$, $j$bat-benh$j$, $j$🐛 Mặt đất chậu cây mọc mốc trắng: có hại không, vì sao xuất hiện và xử lý thế nào$j$, $j$Lớp mốc trắng như bông hoặc như bột trên mặt đất chậu thường là nấm hoại sinh phân hủy mùn, không trực tiếp hại cây. Mốc xuất hiện khi đất ẩm lâu, thiếu thoáng, có phân hữu cơ chưa hoai. Cạo bỏ lớp mặt, để đất khô hơn, đặt chậu nơi thoáng là hết. Cần cảnh giác nếu tơ trắng bao quanh gốc.$j$, $j$[{"type": "p", "text": "Thay đất, bón phân hữu cơ được vài tuần, mặt chậu bỗng phủ một lớp mốc trắng như bông gòn hay như rắc bột. Phần lớn trường hợp đây là nấm \"dọn rác\" đang phân hủy mùn trong đất — không nguy hiểm, nhưng là dấu hiệu chậu đang quá ẩm."}, {"type": "h2", "text": "🔎 Vì sao mặt đất chậu bị mốc trắng?"}, {"type": "list", "items": ["Đất ẩm kéo dài, tưới quá nhiều hoặc chậu không thoát nước.", "Chậu đặt chỗ kín gió, thiếu sáng (góc phòng, gầm cầu thang).", "Trộn phân chuồng, phân trùn quế, xơ dừa, trấu chưa hoai: nấm phát triển để phân hủy chúng.", "Mùa mưa ở miền Tây không khí ẩm cao, mốc mọc nhanh hơn."], "ordered": false}, {"type": "h2", "text": "⚠️ Mốc nào đáng lo?"}, {"type": "p", "text": "Cần phân biệt với **nấm hạch trắng** gây [thối gốc](/benh-cay/thoi-goc-nam-hach): tơ trắng **bao quanh cổ rễ, bò lên gốc thân**, kèm những hạt tròn nhỏ như hạt cải màu trắng rồi nâu; gốc cây thâm, cây héo. Trường hợp này phải xử lý ngay. Còn mốc chỉ nằm trên mặt đất, cách xa gốc, cây vẫn xanh tốt thì không đáng lo."}, {"type": "h2", "text": "🛠️ Xử lý mốc trên mặt chậu"}, {"type": "list", "items": ["Cạo bỏ lớp đất mặt 1–2cm có mốc, thay bằng đất sạch khô.", "Giảm tưới: chờ mặt đất khô mới tưới lại.", "Dời chậu ra chỗ thoáng, có ánh sáng; xới nhẹ mặt đất cho thông khí.", "Có thể rắc mỏng một lớp quế bột hoặc than hoạt tính lên mặt đất — cách dân gian giúp hạn chế nấm.", "Đổ bỏ nước đọng dưới đĩa."], "ordered": false}, {"type": "h2", "text": "🛡️ Phòng mốc tái phát"}, {"type": "p", "text": "Chỉ dùng phân hữu cơ đã hoai hẳn (không mùi hôi, tơi vụn); dùng giá thể thoát nước; trộn chế phẩm [Trichoderma](/goc-cham-cay/trichoderma-che-pham-sinh-hoc) khi thay đất để nấm có ích lấn át nấm hại. Xem thêm [phân hữu cơ cho cây cảnh dùng sao cho không hôi](/goc-cham-cay/phan-huu-co-cho-cay-canh)."}]$j$, NULL, 2, ARRAY[$j$thoi-goc-nam-hach$j$,$j$thoi-re$j$]::text[], ARRAY[$j$mốc trắng$j$,$j$đất chậu$j$,$j$nấm$j$]::text[], $j$Mốc trắng trên mặt đất chậu cây có hại không? Nguyên nhân do đất ẩm, phân chưa hoai; cách xử lý và phân biệt với nấm trắng thối gốc nguy hiểm.$j$, $j$2026-11-01 19:30:00+07$j$),
($j$trong-cay-chau-khong-lo-thoat-nuoc$j$, $j$cham-soc$j$, $j$🪴 Chậu sứ không lỗ thoát nước: có trồng cây được không và cách dùng để cây không úng rễ$j$, $j$Trồng thẳng cây vào chậu sứ không lỗ thoát nước rất dễ úng rễ vì nước dư không có chỗ thoát. Cách an toàn nhất: trồng cây trong chậu nhựa có lỗ rồi đặt lồng vào chậu sứ làm vỏ, kê sỏi dưới đáy và đổ nước đọng sau mỗi lần tưới. Nếu buộc trồng trực tiếp, phải tưới rất ít và lót lớp sỏi dày.$j$, $j$[{"type": "p", "text": "Chậu sứ, chậu gốm tráng men đẹp sang nhưng nhiều chiếc không có lỗ thoát nước ở đáy. Trồng thẳng cây vào đó, mỗi lần tưới dư nước sẽ đọng ở đáy chậu — lâu ngày rễ thiếu khí, thối dần mà bên ngoài không thấy."}, {"type": "image", "file": "https://pd.w.org/2025/07/192687c82a3a92579.44164725-1536x2048.jpeg", "caption": "Cây kiểng lá trong chậu sứ trang trí"}, {"type": "h2", "text": "💡 Cách tốt nhất: chậu lồng chậu"}, {"type": "list", "items": ["Để cây ở chậu nhựa có lỗ thoát nước (thường là chậu nhà vườn khi mua về).", "Lót 2–3cm sỏi hoặc đặt miếng kê dưới đáy chậu sứ.", "Đặt chậu nhựa lên trên, sao cho đáy chậu nhựa cao hơn mực nước có thể đọng.", "Phủ rêu khô, sỏi trắng hoặc vỏ thông lên khe giữa hai chậu để che chậu nhựa.", "Sau khi tưới 15–20 phút, nghiêng chậu sứ hoặc nhấc chậu nhựa ra đổ nước đọng."], "ordered": true}, {"type": "p", "text": "Cách này còn tiện: muốn thay cây, đổi chậu theo mùa hay mang cây đi tắm lá chỉ cần nhấc chậu nhựa ra. Cỡ chậu nhựa theo mã C của nhà vườn xem ở bài [chọn chậu và cỡ cây](/goc-cham-cay/chon-chau-va-co-cay-ma-chau-c)."}, {"type": "h2", "text": "⚠️ Nếu buộc phải trồng trực tiếp"}, {"type": "list", "items": ["Lót lớp sỏi, đá nhỏ dày 1/5 chiều cao chậu để có chỗ chứa nước dư.", "Dùng giá thể rất thoát nước (xơ dừa, trấu hun, perlite).", "Tưới **ít và đo lượng**: khoảng 1/4–1/5 thể tích đất mỗi lần, chờ đất khô hẳn mới tưới lại.", "Chỉ trồng cây chịu hạn (lưỡi hổ, ngọc bích); tránh cây cần ẩm nhiều.", "Có thể khoan lỗ đáy bằng mũi khoan kính/gạch chuyên dụng nếu chậu cho phép."], "ordered": false}, {"type": "h2", "text": "🔍 Dấu hiệu cây trong chậu kín bị úng"}, {"type": "p", "text": "Lá vàng từ dưới lên, đất có mùi hôi chua, lá rũ dù đất ướt, ruồi nhỏ bay quanh chậu (ruồi nấm đất). Gặp các dấu hiệu này, nhấc cây ra kiểm tra rễ ngay — xem [thối rễ](/benh-cay/thoi-re)."}, {"type": "products", "title": "Cây chịu khô hợp chậu trang trí", "slugs": ["luoi-ho", "ngoc-bich", "trau-ba-de-vuong-xanh"]}]$j$, $j$https://pd.w.org/2025/07/192687c82a3a92579.44164725-1536x2048.jpeg$j$, 2, ARRAY[$j$thoi-re$j$]::text[], ARRAY[$j$chậu không lỗ$j$,$j$chậu sứ$j$,$j$úng rễ$j$]::text[], $j$Chậu sứ, chậu gốm không lỗ thoát nước có trồng cây được không? Cách lồng chậu nhựa vào chậu sứ, lót sỏi, tưới đúng lượng để cây không úng rễ.$j$, $j$2026-11-02 06:30:00+07$j$),
($j$trong-dua-leo-san-thuong$j$, $j$rau-sach$j$, $j$🥬 Trồng dưa leo trên sân thượng: làm giàn, tưới đều, thụ phấn để trái thẳng, không đắng$j$, $j$Dưa leo trồng chậu cho trái sau khoảng 35–45 ngày nếu đủ nắng, tưới đều và có giàn leo. Chọn thùng sâu 30cm, đất giàu mùn, cắm giàn khi cây ra tua cuốn. Tưới đều mỗi ngày để trái không đắng, cong; sân thượng ít ong thì thụ phấn bằng tay buổi sáng.$j$, $j$[{"type": "p", "text": "Dưa leo hái tận giàn giòn, thơm, ăn sống hay chấm mắm đều ngon. Trên sân thượng nhà phố, vài thùng xốp và một khung giàn đơn giản là đủ có dưa ăn hằng ngày trong mùa."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Starr-220604-0502-Cucumis_sativus-Marketmore_vine_on_trellis-Hawea_Pl_Olinda-Maui_%2852449316933%29.jpg/960px-Starr-220604-0502-Cucumis_sativus-Marketmore_vine_on_trellis-Hawea_Pl_Olinda-Maui_%2852449316933%29.jpg", "caption": "Dưa leo leo giàn. Ảnh: Forest and Kim Starr, CC BY 2.0, Wikimedia Commons"}, {"type": "h2", "text": "🌱 Gieo hạt"}, {"type": "list", "items": ["Ngâm hạt nước ấm 3–4 tiếng, ủ khăn ẩm đến khi nứt nanh.", "Gieo 2–3 hạt mỗi hốc, sâu 1–1,5cm; giữ lại 1–2 cây khỏe khi có 2 lá thật.", "Mỗi thùng xốp lớn trồng 2–3 cây."], "ordered": false}, {"type": "h2", "text": "🪴 Đất và thùng"}, {"type": "p", "text": "Thùng sâu ít nhất 30cm, có lỗ thoát nước; đất tơi giàu mùn (đất thịt + phân chuồng hoai + xơ dừa). Đặt nơi nắng 6 giờ/ngày trở lên."}, {"type": "h2", "text": "🪜 Làm giàn"}, {"type": "p", "text": "Khi cây ra tua cuốn (khoảng 2 tuần sau gieo), cắm giàn chữ A hoặc căng lưới cao 1,5–2m. Giàn chắc vì lúc nhiều trái khá nặng; sân thượng gió mạnh thì buộc thêm dây néo."}, {"type": "h2", "text": "💧 Tưới và bón"}, {"type": "list", "items": ["Tưới gốc mỗi ngày, ngày nắng gắt tưới hai lần; **tưới đều** là bí quyết để trái không đắng, không cong queo.", "Tránh tưới lên lá buổi chiều tối (dễ bệnh phấn trắng, sương mai).", "Bón phân hữu cơ 7–10 ngày một lần; khi ra hoa, nuôi trái tăng phân có kali."], "ordered": false}, {"type": "h2", "text": "🌼 Thụ phấn bằng tay"}, {"type": "p", "text": "Dưa leo có hoa đực và hoa cái riêng (hoa cái có trái non nhỏ ngay dưới cánh hoa). Sân thượng ít ong thì sáng sớm hái hoa đực, bỏ cánh, quẹt nhị vào nhụy hoa cái. Hoa cái không được thụ phấn sẽ héo, trái non vàng rụng."}, {"type": "h2", "text": "🐛 Sâu bệnh hay gặp"}, {"type": "list", "items": ["[Phấn trắng](/benh-cay/phan-trang) trên lá mùa khô.", "Bọ trĩ, rệp, bọ phấn ở đọt non — xem [bọ trĩ](/benh-cay/bo-tri).", "Ruồi đục trái: bao trái non bằng túi giấy.", "[Héo xanh vi khuẩn](/benh-cay/heo-xanh-vi-khuan): nhổ bỏ cây."], "ordered": false}, {"type": "h2", "text": "✂️ Thu hoạch"}, {"type": "p", "text": "Khoảng 35–45 ngày sau gieo, hái trái khi còn non, vỏ xanh bóng, gai mềm. Hái thường xuyên để cây tiếp tục ra trái; để trái già trên cây làm cây nhanh tàn."}, {"type": "p", "text": "Xem thêm [trồng cà chua chậu](/goc-cham-cay/trong-ca-chua-chau) và [trồng ớt chậu](/goc-cham-cay/trong-ot-chau)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Starr-220604-0502-Cucumis_sativus-Marketmore_vine_on_trellis-Hawea_Pl_Olinda-Maui_%2852449316933%29.jpg/960px-Starr-220604-0502-Cucumis_sativus-Marketmore_vine_on_trellis-Hawea_Pl_Olinda-Maui_%2852449316933%29.jpg$j$, 2, '{}'::text[], ARRAY[$j$dưa leo$j$,$j$rau sạch$j$,$j$sân thượng$j$]::text[], $j$Cách trồng dưa leo trong chậu, thùng trên sân thượng: gieo hạt, làm giàn, tưới, bón phân, thụ phấn bằng tay, phòng sâu bệnh và thu hái trái non giòn ngọt.$j$, $j$2026-11-02 19:30:00+07$j$),
($j$rep-sap-re-cay-trong-chau$j$, $j$bat-benh$j$, $j$🐛 Rệp sáp hại rễ cây trồng chậu: cây còi cọc, héo mà không rõ lý do — cách kiểm tra và xử lý$j$, $j$Rệp sáp rễ sống trong đất, bám quanh rễ thành những đốm trắng như mốc bông, hút nhựa làm cây còi cọc, vàng lá, héo dù tưới đủ. Kiểm tra bằng cách nhấc cây khỏi chậu xem bầu rễ. Xử lý: rũ bỏ đất cũ, rửa rễ, cắt rễ hư, ngâm rễ, trồng lại bằng đất mới và chậu sạch.$j$, $j$[{"type": "p", "text": "Cây tưới đủ, bón đủ mà vẫn còi cọc, lá vàng nhạt, trưa nắng là héo — trên lá không thấy sâu bệnh gì. Lúc đó nên nghĩ tới thứ nằm dưới đất: **rệp sáp rễ**. Chúng hay gặp ở cây mọng nước, lưỡi hổ, cây kiểng lá, cây ăn trái trồng chậu lâu năm."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Mealybug_on_Ghaf_%28Prosopis_cineraria%29_tree_in_India_02.jpg/960px-Mealybug_on_Ghaf_%28Prosopis_cineraria%29_tree_in_India_02.jpg", "caption": "Rệp sáp phủ lớp sáp trắng như bông. Ảnh: Suyash Dwivedi, CC BY-SA 4.0, Wikimedia Commons"}, {"type": "h2", "text": "🔍 Dấu hiệu cây bị rệp sáp rễ"}, {"type": "list", "items": ["Cây lớn chậm hẳn, lá nhỏ, vàng nhạt dần, không có đốm bệnh rõ ràng.", "Héo vào buổi trưa dù đất còn ẩm.", "Nhấc cây ra khỏi chậu: thấy **đốm trắng như mốc bông** bám quanh rễ và thành chậu, bóp ra có con rệp nhỏ màu trắng hồng.", "Đôi khi thấy rệp bò lên cổ rễ sát mặt đất."], "ordered": false}, {"type": "p", "text": "Đừng nhầm với mốc trắng hoại sinh (dạng tơ, không có con) hay [tuyến trùng](/benh-cay/tuyen-trung-sung-re) (rễ nổi u bướu)."}, {"type": "h2", "text": "🛠️ Cách xử lý rệp sáp rễ"}, {"type": "list", "items": ["Nhấc cây ra, rũ bỏ toàn bộ đất cũ (bỏ đi, không dùng lại).", "Rửa sạch bộ rễ dưới vòi nước, dùng bàn chải mềm chải những chỗ có sáp trắng.", "Cắt bỏ rễ thối, rễ khô, phần rễ bám rệp dày đặc.", "Ngâm rễ vào nước ấm khoảng 45°C trong 5–10 phút (cách nhà vườn hay dùng với cây khỏe, rễ chắc) hoặc nhúng rễ qua dung dịch xà phòng sinh học pha loãng rồi rửa lại.", "Rửa chậu bằng xà phòng, phơi nắng; hoặc dùng chậu mới.", "Trồng lại bằng đất mới, để chỗ râm 1 tuần, tưới vừa phải."], "ordered": true}, {"type": "note", "title": "⚠️ Lưu ý an toàn", "text": "Ngâm nước ấm chỉ áp dụng cho cây khỏe, nhiệt độ vừa đủ ấm tay; nước quá nóng làm chết rễ. Nếu dùng thuốc bảo vệ thực vật xử lý đất, chọn thuốc có đăng ký và đọc kỹ nhãn."}, {"type": "h2", "text": "🛡️ Phòng rệp sáp rễ"}, {"type": "list", "items": ["Cây mới mua về: nhấc nhẹ ra xem bầu rễ trước khi đặt cạnh cây khác.", "Không dùng lại đất cũ của chậu cây bị bệnh.", "Thay chậu định kỳ ([thay chậu đúng cách](/goc-cham-cay/thay-chau-cay-canh-dung-cach)) cũng là dịp kiểm tra rễ.", "Rệp sáp trên thân lá: xử lý sớm (xem [rệp sáp](/benh-cay/rep-sap)) để không lan xuống đất."], "ordered": false}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Mealybug_on_Ghaf_%28Prosopis_cineraria%29_tree_in_India_02.jpg/960px-Mealybug_on_Ghaf_%28Prosopis_cineraria%29_tree_in_India_02.jpg$j$, 2, ARRAY[$j$rep-sap$j$,$j$tuyen-trung-sung-re$j$]::text[], ARRAY[$j$rệp sáp rễ$j$,$j$cây còi cọc$j$,$j$sâu hại$j$]::text[], $j$Rệp sáp rễ (rệp sáp hại rễ) trên cây trồng chậu: dấu hiệu cây còi, héo, vàng lá; cách nhấc chậu kiểm tra, rửa rễ, thay đất và phòng lây lan.$j$, $j$2026-11-03 06:30:00+07$j$),
($j$phun-suong-cho-cay-khi-nao-nen$j$, $j$cham-soc$j$, $j$💦 Phun sương cho cây: cây nào cần, lúc nào nên phun và khi nào phun sương lại làm hại cây$j$, $j$Phun sương giúp cây lá mỏng ưa ẩm như đuôi công, dương xỉ, lan ý đỡ khô mép lá trong phòng máy lạnh hay mùa khô. Nên phun buổi sáng, hạt nhỏ, vừa đủ làm ẩm lá. Không cần phun cho cây lá dày, cây mọng nước; không phun buổi tối hay lúc nắng gắt vì dễ sinh nấm, cháy lá.$j$, $j$[{"type": "p", "text": "Bình phun sương là món đồ quen thuộc của người trồng cây trong nhà. Nhưng phun sai cây, sai giờ thì không những vô ích mà còn làm cây bị nấm, thối nõn."}, {"type": "h2", "text": "🔎 Phun sương có tác dụng gì?"}, {"type": "list", "items": ["Tăng độ ẩm quanh lá trong thời gian ngắn — giảm khô mép lá ở cây ưa ẩm.", "Rửa bụi trên lá.", "Làm môi trường kém thuận lợi cho [nhện đỏ](/benh-cay/nhen-do) (chúng thích khô).", "Không thay được tưới gốc: rễ vẫn cần nước từ đất."], "ordered": false}, {"type": "h2", "text": "🛒 Cây nào cần, cây nào không?"}, {"type": "table", "rows": [["Nên phun", "Không cần / không nên phun"], ["Đuôi công (Calathea)", "Lưỡi hổ"], ["Dương xỉ", "Ngọc bích, sen đá, xương rồng"], ["Lan ý", "Cây lá có lông tơ (lá nhung)"], ["Môn, Alocasia (vừa phải)", "Cây đang ra hoa — phun lên hoa dễ úng cánh"]]}, {"type": "h2", "text": "⏰ Phun lúc nào, phun bao nhiêu?"}, {"type": "list", "items": ["**Buổi sáng** là tốt nhất: lá kịp khô trước tối.", "Không phun buổi tối: lá ướt qua đêm dễ [đốm lá do nấm](/benh-cay/dom-la-nam).", "Không phun khi nắng chiếu trực tiếp lên lá ngoài trời.", "Phun hạt thật nhỏ, đủ làm ẩm bề mặt lá, không để nước nhỏ giọt, đọng ở nõn.", "Phòng máy lạnh: 1 lần mỗi ngày hoặc cách ngày; mùa mưa thường không cần.", "Dùng nước để qua đêm hoặc nước mưa, tránh vệt trắng trên lá do khoáng."], "ordered": false}, {"type": "h2", "text": "💡 Cách tăng ẩm bền hơn phun sương"}, {"type": "p", "text": "Phun sương chỉ giữ ẩm vài phút. Muốn bền hơn: đặt chậu trên khay sỏi có nước, gom nhiều cây gần nhau, đặt cây xa cửa gió máy lạnh. Xem thêm [cây văn phòng chịu bóng](/goc-cham-cay/cay-van-phong-chiu-bong-it-tuoi) và [cây đuôi công giữ lá không cháy mép](/goc-cham-cay/phan-biet-cay-duoi-cong-calathea)."}, {"type": "products", "title": "Cây ưa ẩm cần phun sương", "slugs": ["duoi-cong-xanh", "duoi-cong-tim", "duong-xi", "lan-y"]}]$j$, NULL, 2, ARRAY[$j$dom-la-nam$j$,$j$nhen-do$j$]::text[], ARRAY[$j$phun sương$j$,$j$độ ẩm$j$,$j$cây trong nhà$j$]::text[], $j$Phun sương cho cây cảnh: cây nào cần (đuôi công, dương xỉ, lan ý), cây nào không (lưỡi hổ, sen đá), lúc nào, bao nhiêu và khi nào phun sương làm cây bị nấm.$j$, $j$2026-11-03 12:00:00+07$j$),
($j$trong-gung-nghe-trong-thung$j$, $j$rau-sach$j$, $j$🥬 Trồng gừng, nghệ trong thùng xốp, bao tải từ củ mua chợ: 8–10 tháng có củ thu hoạch$j$, $j$Gừng và nghệ trồng dễ từ củ mua chợ: chọn củ có mắt mầm, ủ ẩm cho nhú mầm rồi trồng sâu 5cm trong thùng hoặc bao đất tơi. Cây ưa bóng nhẹ, đất ẩm thoát nước, trồng đầu mùa mưa là tốt nhất. Lá vàng úa là lúc thu củ, thường sau 8–10 tháng; có thể bẻ nhánh củ non dùng sớm hơn.$j$, $j$[{"type": "p", "text": "Gừng, nghệ là gia vị và vị thuốc dân gian quen thuộc. Trồng trong thùng xốp hay bao tải ở góc sân, ít tốn công, lại có lá xanh mướt quanh năm. Đầu mùa mưa ở miền Tây là thời điểm trồng thuận lợi nhất."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Ingwer_%28Zingiber_officinale%29_Freiland_Anbau_Pflanze-2-Josef_Schlaghecken.jpg/960px-Ingwer_%28Zingiber_officinale%29_Freiland_Anbau_Pflanze-2-Josef_Schlaghecken.jpg", "caption": "Cây gừng trồng tại nhà. Ảnh: Schlaghecken Josef, CC BY-SA 4.0, Wikimedia Commons"}, {"type": "h2", "text": "🌱 Chọn và ủ củ giống"}, {"type": "list", "items": ["Chọn củ chắc, vỏ căng, có nhiều **mắt mầm** (u nhỏ màu vàng, hồng ở đầu củ).", "Bẻ thành đoạn 3–5cm, mỗi đoạn có 2–3 mắt; để khô vết bẻ 1 ngày.", "Ủ trong cát ẩm hoặc khăn ẩm nơi râm 1–2 tuần cho mầm nhú."], "ordered": false}, {"type": "h2", "text": "🪴 Trồng"}, {"type": "list", "items": ["Thùng xốp, bao tải hoặc chậu sâu 30cm trở lên, đáy có lỗ.", "Đất tơi xốp giàu mùn, thoát nước: đất + phân chuồng hoai + trấu hun.", "Đặt củ nằm ngang, mầm hướng lên, sâu khoảng 5cm, cách nhau 15–20cm.", "Nơi có nắng sáng hoặc bóng nhẹ; nắng gắt cả ngày lá dễ cháy."], "ordered": false}, {"type": "h2", "text": "💧 Tưới, bón, vun gốc"}, {"type": "list", "items": ["Giữ đất ẩm đều, không để úng — củ ngâm nước sẽ thối.", "1 tháng một lần bón phân hữu cơ quanh gốc.", "Khi củ nhô lên mặt đất, vun thêm đất (hoặc thêm đất vào bao) để củ to và không bị xanh.", "Mùa khô tưới thường xuyên hơn; phủ rơm mặt đất giữ ẩm."], "ordered": false}, {"type": "h2", "text": "✂️ Thu hoạch"}, {"type": "p", "text": "Sau 8–10 tháng, khi lá vàng úa dần là củ đã già, đào lên dùng hoặc giữ làm giống. Muốn dùng gừng non (gừng ngó hồng làm mứt, gừng tươi) có thể bới nhẹ, bẻ nhánh củ non sau 4–5 tháng rồi lấp đất lại."}, {"type": "note", "title": "💡 Gừng, nghệ mua chợ có trồng được không?", "text": "Được, nếu củ còn mắt mầm khỏe. Một số củ đã qua xử lý bảo quản lâu sẽ nhú mầm chậm hoặc không nhú — chọn củ tươi, vỏ căng, mua ở chợ quê thường dễ lên hơn."}, {"type": "p", "text": "Xem thêm [trồng hành lá từ gốc hành mua chợ](/goc-cham-cay/trong-hanh-la-tai-nha) và [ủ phân hữu cơ từ rác bếp](/goc-cham-cay/u-phan-huu-co-tu-rac-bep)."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Ingwer_%28Zingiber_officinale%29_Freiland_Anbau_Pflanze-2-Josef_Schlaghecken.jpg/960px-Ingwer_%28Zingiber_officinale%29_Freiland_Anbau_Pflanze-2-Josef_Schlaghecken.jpg$j$, 2, '{}'::text[], ARRAY[$j$gừng$j$,$j$nghệ$j$,$j$rau gia vị$j$]::text[], $j$Cách trồng gừng, nghệ trong thùng xốp, bao tải tại nhà từ củ mua chợ: ủ mầm, đất, tưới, bón, vun gốc và thu hoạch củ sau 8–10 tháng.$j$, $j$2026-11-03 19:30:00+07$j$),
($j$cay-heo-du-dat-con-uot$j$, $j$bat-benh$j$, $j$🐛 Cây héo rũ dù đất vẫn còn ướt: 5 nguyên nhân thường gặp và cách cứu kịp thời$j$, $j$Cây héo mà đất còn ướt thường không phải do thiếu nước mà do rễ không hút được nước: rễ thối vì úng, rễ bị sốc nhiệt, cây vừa thay chậu, sâu bệnh hại rễ hoặc bệnh héo do vi khuẩn. Đừng tưới thêm; hãy kiểm tra rễ, để đất khô và dời cây vào chỗ râm mát.$j$, $j$[{"type": "p", "text": "Thấy cây rũ lá, phản xạ đầu tiên của hầu hết mọi người là tưới thêm nước. Nhưng nếu đất trong chậu vẫn còn ẩm ướt mà cây vẫn héo, tưới thêm là đẩy cây tới chỗ chết nhanh hơn. Héo khi đất ướt nghĩa là **rễ không đưa được nước lên lá**."}, {"type": "image", "file": "https://live.staticflickr.com/5029/5684778520_6b5d7e1f7e_b.jpg", "caption": "Cây trồng chậu héo rũ lá"}, {"type": "h2", "text": "🔎 5 nguyên nhân cây héo khi đất còn ướt"}, {"type": "h3", "text": "1. Thối rễ do úng nước"}, {"type": "p", "text": "Nguyên nhân phổ biến nhất. Rễ ngâm nước lâu bị thiếu khí, nấm tấn công, rễ chuyển nâu đen, mềm nhũn, có mùi hôi. Xem [thối rễ](/benh-cay/thoi-re) và [5 dấu hiệu thối rễ mùa mưa](/goc-cham-cay/5-dau-hieu-thoi-re-mua-mua)."}, {"type": "h3", "text": "2. Nắng nóng gắt giữa trưa"}, {"type": "p", "text": "Lá thoát nước nhanh hơn rễ hút được nên cây rũ tạm thời, chiều mát tự đứng lên. Đây là héo sinh lý, không cần tưới thêm — chỉ cần che nắng trưa."}, {"type": "h3", "text": "3. Cây vừa thay chậu, vừa chuyển chỗ"}, {"type": "p", "text": "Rễ bị đứt, cây cần 1–2 tuần để hồi. Để chỗ râm mát, giữ ẩm vừa phải, không bón phân."}, {"type": "h3", "text": "4. Rễ bị sâu hại"}, {"type": "p", "text": "Rệp sáp rễ, tuyến trùng làm rễ mất khả năng hút nước — xem [rệp sáp hại rễ](/benh-cay/rep-sap) và [tuyến trùng sưng rễ](/benh-cay/tuyen-trung-sung-re)."}, {"type": "h3", "text": "5. Héo xanh do vi khuẩn"}, {"type": "p", "text": "Cây héo rũ đột ngột khi lá còn xanh, hay gặp trên cà chua, ớt, cà tím. Cắt ngang gốc thân nhúng vào ly nước thấy dịch trắng đục chảy ra như sợi khói. Bệnh không chữa được, phải nhổ bỏ — xem [héo xanh vi khuẩn](/benh-cay/heo-xanh-vi-khuan)."}, {"type": "h2", "text": "🛠️ Cách cứu cây héo khi đất còn ướt"}, {"type": "list", "items": ["Ngưng tưới ngay.", "Dời cây vào chỗ râm mát, thoáng gió.", "Nhấc cây ra khỏi chậu xem rễ: rễ trắng chắc là khỏe; rễ nâu đen, mềm, hôi là thối.", "Cắt bỏ rễ thối bằng kéo sạch, để rễ khô thoáng vài giờ.", "Trồng lại bằng đất mới thoát nước tốt, chậu có lỗ; tỉa bớt lá nếu rễ còn quá ít.", "Tưới nhẹ sau 2–3 ngày, giữ chỗ râm 1–2 tuần."], "ordered": true}, {"type": "table", "rows": [["Kiểm tra", "Héo do thiếu nước", "Héo do rễ hỏng"], ["Đất", "Khô, nhẹ chậu", "Ẩm hoặc sũng"], ["Sau khi tưới", "Tươi lại sau vài giờ", "Không tươi lại, tệ hơn"], ["Rễ", "Trắng, chắc", "Nâu đen, mềm, có mùi"]]}, {"type": "p", "text": "Xem thêm [héo do thiếu nước](/benh-cay/heo-thieu-nuoc) để so sánh."}]$j$, $j$https://live.staticflickr.com/5029/5684778520_6b5d7e1f7e_b.jpg$j$, 2, ARRAY[$j$thoi-re$j$,$j$heo-xanh-vi-khuan$j$,$j$heo-thieu-nuoc$j$]::text[], ARRAY[$j$cây héo$j$,$j$thối rễ$j$,$j$bắt bệnh cây$j$]::text[], $j$Cây héo rũ dù đất còn ướt là do đâu? 5 nguyên nhân: thối rễ, sốc nhiệt, mới thay chậu, rệp hại rễ, héo xanh vi khuẩn. Cách kiểm tra rễ và cứu cây.$j$, $j$2026-11-04 06:30:00+07$j$),
($j$trong-cay-thuy-sinh-trong-nuoc$j$, $j$cham-soc$j$, $j$🌿 Trồng cây thủy sinh trong bình nước tại nhà: cây nào trồng được, thay nước và bón phân thế nào$j$, $j$Nhiều cây kiểng lá sống tốt trong bình nước: phú quý, ngọc ngân, trầu bà, lan ý, lan chi, vạn lộc. Rửa sạch đất ở rễ, chỉ cho nước ngập phần rễ, đặt nơi sáng tán xạ, thay nước 5–7 ngày một lần và nhỏ vài giọt phân thủy sinh mỗi tháng. Bình thủy tinh trong cần tránh nắng để không mọc rêu.$j$, $j$[{"type": "p", "text": "Một bình thủy tinh trong, thấy rõ bộ rễ trắng muốt và vài lá xanh — cây thủy sinh để bàn vừa sạch sẽ (không đất, không côn trùng đất) vừa ít phải chăm. Không phải cây nào cũng sống được trong nước, nhưng khá nhiều cây kiểng lá quen thuộc làm được."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Ficus_cuttings_with_roots_in_a_bottle..jpg/960px-Ficus_cuttings_with_roots_in_a_bottle..jpg", "caption": "Cành cây ra rễ trong bình nước. Ảnh: Biusch, CC BY-SA 3.0, Wikimedia Commons"}, {"type": "h2", "text": "🛒 Cây nào trồng thủy sinh được?"}, {"type": "table", "rows": [["Dễ trồng nước", "Lưu ý"], ["Phú quý, vạn lộc, ngọc ngân (Aglaonema)", "Rất bền, lá màu đẹp"], ["Trầu bà các loại", "Ra rễ nhanh từ đốt thân"], ["Lan ý", "Vẫn ra hoa nếu đủ sáng"], ["Lan chi", "Dùng cây con trên nhánh rủ"], ["Không nên", "Cây mọng nước (lưỡi hổ lớn, ngọc bích), cây ăn trái"]]}, {"type": "h2", "text": "🛠️ Chuyển cây từ đất sang nước"}, {"type": "list", "items": ["Nhấc cây khỏi chậu, rũ đất, ngâm rửa rễ thật sạch dưới vòi nước nhẹ.", "Cắt bỏ rễ thối, rễ đứt dập; tỉa bớt rễ quá dài.", "Đặt cây vào bình sao cho **nước chỉ ngập rễ**, gốc thân và lá phải ở trên mặt nước.", "Dùng sỏi, đá hoặc nắp xốp có lỗ để giữ cây đứng.", "Vài tuần đầu rễ đất sẽ thoái hóa và mọc rễ nước mới (trắng, mảnh hơn) — thay nước 3–4 ngày một lần trong giai đoạn này."], "ordered": true}, {"type": "h2", "text": "💧 Thay nước và bón phân"}, {"type": "list", "items": ["Thay nước 5–7 ngày một lần; dùng nước để qua đêm.", "Rửa sạch nhớt bám ở rễ và thành bình khi thay.", "Mỗi tháng nhỏ vài giọt **phân thủy sinh** theo hướng dẫn; không dùng phân bón đất.", "Nước đục, có mùi: thay ngay, kiểm tra rễ thối."], "ordered": false}, {"type": "h2", "text": "☀️ Đặt bình ở đâu?"}, {"type": "p", "text": "Nơi sáng tán xạ, **không có nắng chiếu thẳng vào bình** — nắng làm nước nóng và rêu xanh mọc nhanh trong bình thủy tinh. Rêu nhiều thì dùng bình màu hoặc bình mờ."}, {"type": "h2", "text": "❓ Cây thủy sinh có sống lâu không?"}, {"type": "p", "text": "Có thể sống nhiều năm nếu thay nước đều và bổ sung dinh dưỡng, nhưng thường lớn chậm hơn trồng đất. Khi cây quá lớn so với bình, có thể tách bớt hoặc chuyển ra trồng đất. Xem thêm [phân biệt phú quý, vạn lộc, ngọc ngân](/goc-cham-cay/phan-biet-phu-quy-van-loc-ngoc-ngan-ngan-hau)."}, {"type": "products", "title": "Cây trồng thủy sinh được", "slugs": ["phu-quy", "ngoc-ngan", "van-loc", "lan-y", "lan-chi"]}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Ficus_cuttings_with_roots_in_a_bottle..jpg/960px-Ficus_cuttings_with_roots_in_a_bottle..jpg$j$, 2, ARRAY[$j$thoi-re$j$]::text[], ARRAY[$j$cây thủy sinh$j$,$j$trồng cây trong nước$j$,$j$cây để bàn$j$]::text[], $j$Cách trồng cây thủy sinh trong bình nước tại nhà: cây nào trồng được, cách chuyển cây từ đất sang nước, thay nước, bón phân, xử lý rêu và thối rễ.$j$, $j$2026-11-04 19:30:00+07$j$),
($j$la-non-bi-xoan-bien-dang$j$, $j$bat-benh$j$, $j$🐛 Lá non bị xoăn, quăn queo, biến dạng: do rệp, bọ trĩ, nhện, virus hay do thời tiết?$j$, $j$Lá non xoăn và biến dạng thường do côn trùng chích hút ở đọt (rệp muội, bọ trĩ, nhện trắng), do virus truyền qua bọ phấn, rệp, hoặc do nắng nóng, gió khô và thuốc phun quá liều. Soi kỹ mặt dưới lá và đọt non bằng kính lúp là cách phân biệt nhanh nhất trước khi xử lý.$j$, $j$[{"type": "p", "text": "Lá non vừa nhú đã xoăn tít, mép cong lên hay cong xuống, có khi nhăn nhúm như giấy vò — đó là tín hiệu đọt non đang bị tổn thương. Nguyên nhân có thể là côn trùng rất nhỏ, virus hoặc chỉ là thời tiết. Mỗi nguyên nhân xử lý khác nhau nên cần đoán đúng."}, {"type": "image", "file": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/American_elm_leaves_with_woolly_elm_aphid_infestation_.jpg/960px-American_elm_leaves_with_woolly_elm_aphid_infestation_.jpg", "caption": "Lá non xoăn, biến dạng. Ảnh: Account for test, CC BY-SA 4.0, Wikimedia Commons"}, {"type": "h2", "text": "🔍 Bảng phân biệt nhanh"}, {"type": "table", "rows": [["Dấu hiệu đi kèm", "Nguyên nhân thường gặp"], ["Đám con nhỏ màu xanh, đen ở đọt, lá dính mật", "Rệp muội"], ["Vệt bạc, đốm nâu trên lá, nụ hoa thâm; con thon dài 1–2mm", "Bọ trĩ"], ["Lá non dày, giòn, cong ngược xuống, đọt chùn lại; không thấy con", "Nhện trắng (nhện rất nhỏ, cần kính lúp)"], ["Lá loang xanh vàng như khảm, cây còi; có bọ phấn trắng quanh", "Virus xoăn lá, khảm lá"], ["Xoăn sau đợt nắng nóng, gió khô; lá già không bị", "Thời tiết, thiếu nước"], ["Xoăn đồng loạt ngay sau khi phun thuốc, bón phân lá", "Ngộ độc do phun quá liều"]]}, {"type": "h2", "text": "🛠️ Xử lý theo nguyên nhân"}, {"type": "list", "items": ["**Rệp muội**: xịt nước mạnh, cắt đọt nặng, dùng xà phòng sinh học — xem [rệp muội](/benh-cay/rep-muoi).", "**Bọ trĩ**: cắt bỏ nụ, đọt bị nặng, treo bẫy dính xanh dương hoặc vàng — xem [bọ trĩ](/benh-cay/bo-tri).", "**Nhện**: phun nước mặt dưới lá, tăng độ ẩm — xem [nhện đỏ](/benh-cay/nhen-do).", "**Virus**: không có thuốc chữa. Nhổ bỏ cây bị nặng để khỏi lây, diệt bọ phấn, rệp truyền bệnh — xem [vàng xoăn lá virus](/benh-cay/xoan-la-virus), [khảm lá](/benh-cay/kham-la).", "**Thời tiết**: che nắng trưa, tưới đều; lá mới ra sẽ phẳng lại.", "**Ngộ độc thuốc**: ngưng phun, tưới nước rửa lá; lần sau pha đúng liều, phun lúc chiều mát."], "ordered": false}, {"type": "note", "title": "⚠️ Lưu ý an toàn", "text": "Không phun nhiều loại thuốc trộn chung khi chưa rõ nguyên nhân — dễ làm cây ngộ độc thêm. Nếu dùng thuốc bảo vệ thực vật, chọn thuốc có đăng ký đúng đối tượng và đọc kỹ nhãn. Xem [hướng dẫn dùng thuốc an toàn](/chinh-sach/thuoc-bvtv-an-toan)."}, {"type": "h2", "text": "❓ Lá đã xoăn có phẳng lại được không?"}, {"type": "p", "text": "Lá đã biến dạng thường giữ nguyên hình dạng. Điều cần theo dõi là **lá mới ra sau khi xử lý**: lá mới phẳng, lành lặn nghĩa là đã xử lý đúng. Lá xoăn quá xấu có thể cắt bỏ dần."}]$j$, $j$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/American_elm_leaves_with_woolly_elm_aphid_infestation_.jpg/960px-American_elm_leaves_with_woolly_elm_aphid_infestation_.jpg$j$, 2, ARRAY[$j$xoan-la-virus$j$,$j$bo-tri$j$,$j$rep-muoi$j$,$j$nhen-do$j$]::text[], ARRAY[$j$xoăn lá$j$,$j$bọ trĩ$j$,$j$rệp$j$]::text[], $j$Lá non bị xoăn, quăn, biến dạng là bệnh gì? Phân biệt do rệp muội, bọ trĩ, nhện, virus xoăn lá hay do nắng nóng, thuốc. Cách kiểm tra và xử lý.$j$, $j$2026-11-05 06:30:00+07$j$),
($j$reu-tao-moc-tren-dat-chau-cay$j$, $j$bat-benh$j$, $j$🐛 Rêu xanh, tảo mọc trên mặt đất chậu và thành chậu đất nung: có hại cây không, xử lý ra sao$j$, $j$Rêu và tảo xanh trên mặt đất chậu không hút chất của cây, nhưng báo hiệu đất ẩm thường xuyên và thiếu thoáng. Lớp rêu dày có thể giữ nước, làm mặt đất bí. Cạo bỏ lớp mặt, giảm tưới, cho chậu nhiều ánh sáng và gió hơn là hết. Với chậu đất nung, rêu còn được nhiều người giữ lại làm đẹp.$j$, $j$[{"type": "p", "text": "Mặt đất chậu phủ lớp xanh mướt như nhung, thành chậu đất nung loang lổ màu xanh rêu. Có người thấy đẹp, có người lo cây bệnh. Thực ra rêu và tảo không ăn cây — chúng chỉ cho bạn biết chậu đang ẩm hơn mức cần."}, {"type": "image", "file": "https://pd.w.org/2026/03/29269bd11f19642a0.88733813-2048x1151.jpg", "caption": "Rêu mọc trên mặt đất trồng"}, {"type": "h2", "text": "🔎 Vì sao chậu cây bị rêu, tảo?"}, {"type": "list", "items": ["Đất ẩm liên tục, tưới thường xuyên hoặc tưới phun mưa nhẹ hằng ngày.", "Chậu đặt chỗ râm, ít gió, ánh sáng yếu.", "Nước tưới có nhiều chất dinh dưỡng (phân bón lá rơi xuống đất).", "Chậu đất nung thấm nước qua thành nên mặt ngoài luôn ẩm — rêu mọc rất nhanh."], "ordered": false}, {"type": "h2", "text": "🔍 Rêu có hại cây không?"}, {"type": "p", "text": "Rêu mỏng không hại. Rêu, tảo dày đặc thành lớp nhầy làm mặt đất bí, nước khó thấm xuống, giữ ẩm lâu ở cổ rễ — với cây ưa khô như [lưỡi hổ](/san-pham/luoi-ho), [ngọc bích](/san-pham/ngoc-bich) thì dễ dẫn tới [thối rễ](/benh-cay/thoi-re)."}, {"type": "h2", "text": "🛠️ Xử lý rêu trên mặt chậu"}, {"type": "list", "items": ["Cạo bỏ lớp mặt có rêu, phủ đất mới khô.", "Tưới đẫm một lần rồi chờ mặt đất khô mới tưới tiếp, thay vì tưới ít mỗi ngày.", "Dời chậu ra chỗ sáng, thoáng gió hơn.", "Phủ mặt chậu bằng sỏi, đá trang trí giúp mặt đất khô nhanh.", "Thành chậu đất nung: chà bằng bàn chải với nước pha giấm loãng, rửa sạch, phơi nắng."], "ordered": false}, {"type": "h2", "text": "💡 Khi nào nên giữ rêu?"}, {"type": "p", "text": "Với cây bonsai, tiểu cảnh, cây ưa ẩm như [dương xỉ](/san-pham/duong-xi), lớp rêu mỏng trên mặt chậu giữ ẩm và nhìn rất \"cổ\". Chậu đất nung bám rêu cũng là phong cách được nhiều người thích. Chỉ cần đảm bảo nước vẫn thấm nhanh xuống đất và cổ rễ không bị đọng nước."}, {"type": "p", "text": "Xem thêm [tưới cây trong nhà đúng cách](/goc-cham-cay/tuoi-cay-trong-nha-dung-cach) và [chọn chậu và cỡ cây](/goc-cham-cay/chon-chau-va-co-cay-ma-chau-c)."}]$j$, $j$https://pd.w.org/2026/03/29269bd11f19642a0.88733813-2048x1151.jpg$j$, 2, ARRAY[$j$thoi-re$j$]::text[], ARRAY[$j$rêu$j$,$j$đất chậu$j$,$j$chậu đất nung$j$]::text[], $j$Rêu, tảo xanh mọc trên mặt đất chậu cây và chậu đất nung có hại không? Nguyên nhân, cách cạo bỏ, giảm ẩm và khi nào nên giữ rêu làm đẹp.$j$, $j$2026-11-05 19:30:00+07$j$)) AS v(slug, cat, title, excerpt, body, cover, minutes, diseases, tags, seo, pub)
WHERE NOT EXISTS (SELECT 1 FROM "posts" x WHERE x."slug" = v.slug);
